input, select, textarea { font: inherit; color: inherit; }
ul, ol { list-style: none; }
::selection { background: rgba(201, 163, 90, .32); }
:focus-visible { outline: 1.5px solid var(--gold-hi); outline-offset: 3px; border-radius: 6px; }
::placeholder { color: var(--text-3); }

/* ==========================================================
   2. УТИЛИТЫ
   ========================================================== */
.wrap { width: 100%; max-width: var(--wrap); margin: 0 auto; padding: 0 28px; }
.wrap-wide { width: 100%; max-width: var(--wrap-wide); margin: 0 auto; padding: 0 28px; }
.sr {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap;
}
.skip {
  position: fixed; left: 16px; top: 12px; z-index: 300;
  transform: translateY(-160%);
  padding: 10px 18px; border-radius: 999px;
  background: var(--card); border: 1px solid var(--line-2);
  font-size: 14px; text-decoration: none;
  transition: transform .25s var(--ease);
}
.skip:focus { transform: none; }
.row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.spread { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.muted { color: var(--text-2); }
.dim { color: var(--text-3); }
.nowrap { white-space: nowrap; }
.tnum { font-variant-numeric: tabular-nums; }
.hr { height: 1px; background: var(--line); border: 0; }

/* ==========================================================
   3. ТИПОГРАФИКА
   ========================================================== */
.micro {
  font-size: 12px; letter-spacing: .1em; text-transform: uppercase;
  color: var(--text-3);
}
.kicker { font-size: 13px; color: var(--text-3); letter-spacing: .02em; margin-bottom: 14px; }
.kicker b { color: var(--gold); font-weight: 500; }
.h1 {
  font-family: var(--display); font-weight: 300;
  font-size: clamp(30px, 4.2vw, 62px); line-height: 1.06; letter-spacing: -.025em;
}
.h2 {
  font-family: var(--display); font-weight: 300;
  font-size: clamp(26px, 3.6vw, 44px); line-height: 1.12; letter-spacing: -.015em;
}
.h3 { font-family: var(--display); font-weight: 400; font-size: clamp(18px, 2vw, 23px); line-height: 1.25; }
.h1 em, .h2 em, .h3 em { font-style: normal; color: var(--gold-hi); }
.lead { color: var(--text-2); font-size: 16px; max-width: 58ch; }
.lead-sm { color: var(--text-2); font-size: 14.5px; max-width: 60ch; }
.num {
  font-family: var(--display); font-weight: 200;
  font-variant-numeric: tabular-nums; letter-spacing: -.03em; line-height: 1;
}
.ghost-num {
  font-family: var(--display); font-weight: 200; line-height: .8;
  font-size: clamp(120px, 22vw, 320px);
  color: transparent; -webkit-text-stroke: 1px var(--line-2);
  position: absolute; pointer-events: none; user-select: none;
}
.text-link {
  color: var(--text-2); font-size: 14px; text-underline-offset: 5px;
  text-decoration-color: var(--line-2);
  transition: color .2s, text-decoration-color .2s;
}
.text-link:hover { color: var(--gold-hi); text-decoration-color: var(--gold); }

/* ==========================================================
   4. ИКОНКИ
   ========================================================== */
.ic {
  width: 1em; height: 1em; flex: none;
  display: inline-block; vertical-align: -.125em;
  color: inherit;
}
.ic-14 { font-size: 14px; } .ic-16 { font-size: 16px; } .ic-18 { font-size: 18px; }
.ic-20 { font-size: 20px; } .ic-24 { font-size: 24px; } .ic-32 { font-size: 32px; }
.ic-48 { font-size: 48px; } .ic-72 { font-size: 72px; }
.ic-gold { color: var(--gold); } .ic-blood { color: var(--blood); } .ic-dim { color: var(--text-3); }
.ic-spin { animation: spin 90s linear infinite; transform-origin: 50% 50%; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ==========================================================
   5. КНОПКИ
   ========================================================== */
.btn, .pill {
  display: inline-flex; align-items: center; justify-content: center; gap: .6em;
  height: 44px; padding: 0 20px; border-radius: 999px;
  font-family: var(--ui); font-size: 14.5px; font-weight: 500;
  text-decoration: none; white-space: nowrap; cursor: pointer;
  border: 1px solid transparent; position: relative;
  transition: background .25s, color .25s, border-color .25s, box-shadow .25s, transform .25s var(--ease);
}
.btn:active, .pill:active { transform: scale(.98); }
.btn .ic, .pill .ic { font-size: 17px; }
.btn[disabled], .btn.is-disabled { opacity: .45; pointer-events: none; }

.btn-gold, .pill.solid {
  background: linear-gradient(180deg, var(--gold-hi), var(--gold));
  color: #15110a; border-color: rgba(255, 255, 255, .24);
  box-shadow: 0 14px 34px -16px rgba(201, 163, 90, .8), inset 0 1px 0 rgba(255, 255, 255, .4);
}
.btn-gold:hover, .pill.solid:hover {
  background: linear-gradient(180deg, #f6e4bb, var(--gold-hi));
  box-shadow: 0 16px 40px -14px rgba(201, 163, 90, .95), inset 0 1px 0 rgba(255, 255, 255, .5);
}
.btn-ghost, .pill:not(.solid):not(.btn-gold) {
  border-color: var(--line-2); color: var(--text);
  background: rgba(255, 255, 255, .025);
}
.btn-ghost:hover, .pill:not(.solid):not(.btn-gold):hover {
  border-color: var(--line-3); background: rgba(255, 255, 255, .07);
}
.btn-live {
  background: rgba(201, 79, 67, .13); border-color: rgba(201, 79, 67, .5); color: var(--blood-hi);
}
.btn-live:hover { background: rgba(201, 79, 67, .22); border-color: rgba(201, 79, 67, .75); }
.btn-quiet {
  border-color: transparent; background: none; color: var(--text-2); padding: 0 8px;
}
.btn-quiet:hover { color: var(--text); background: rgba(255, 255, 255, .05); }
.btn-sm { height: 36px; padding: 0 14px; font-size: 13.5px; }
.btn-lg { height: 52px; padding: 0 26px; font-size: 15.5px; }
.btn-block { width: 100%; }
.btn-round { width: 42px; height: 42px; padding: 0; border-radius: 50%; }

/* ==========================================================
   6. СТАТУСЫ
   ========================================================== */
.dot-live {
  position: relative; width: 8px; height: 8px; border-radius: 50%;
  background: var(--blood); flex: none;
}
.dot-live::after {
  content: ''; position: absolute; inset: -3px; border-radius: 50%;
  border: 1px solid var(--blood); animation: ping 2s var(--ease) infinite;
}
@keyframes ping {
  0% { transform: scale(.55); opacity: .9; }
  70% { transform: scale(1.6); opacity: 0; }
  100% { transform: scale(1.6); opacity: 0; }
}
.st {
  display: inline-flex; align-items: center; gap: .5em;
  height: 26px; padding: 0 11px; border-radius: 999px;
  font-size: 12px; letter-spacing: .02em; white-space: nowrap;
