.st-live { color: var(--blood-hi); border-color: rgba(201, 79, 67, .5); background: rgba(201, 79, 67, .12); }
.st-next { color: var(--text); border-color: var(--line-3); background: rgba(255, 255, 255, .06); }
.st-done { color: var(--gold-hi); border-color: rgba(201, 163, 90, .38); background: rgba(201, 163, 90, .1); }
.st-gold { color: var(--gold-hi); border-color: rgba(201, 163, 90, .5); background: rgba(201, 163, 90, .12); }
.st-flag { color: var(--text-3); }

/* ==========================================================
   7. ШАПКА
   ========================================================== */
.site-head {
  position: fixed; inset: 0 0 auto 0; z-index: 90;
  height: var(--head-h); display: flex; align-items: center;
  border-bottom: 1px solid transparent;
  transition: background .35s var(--ease), border-color .35s var(--ease), backdrop-filter .35s;
}
.site-head.solid {
  background: rgba(8, 9, 12, .74);
  -webkit-backdrop-filter: blur(16px) saturate(1.2);
  backdrop-filter: blur(16px) saturate(1.2);
  border-bottom-color: var(--line);

