  background: var(--raise); padding: 16px 18px;
}
.stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }
.stat-plate { border: 1px solid var(--line); border-radius: var(--r-md); padding: 18px 20px; background: var(--raise); }
.stat-plate .v { font-family: var(--display); font-weight: 200; font-size: clamp(24px, 3vw, 34px); line-height: 1; }
.stat-plate .v.gold { color: var(--gold-hi); }
.stat-plate .l { color: var(--text-3); font-size: 12.5px; margin-top: 10px; }

/* ==========================================================
   11. МАТЧ И СЕТКА
   ========================================================== */
.bracket-scroll {
  overflow-x: auto; overflow-y: hidden; padding: 4px 2px 20px;
  scrollbar-width: thin; scrollbar-color: var(--line-2) transparent;
}
.bracket-scroll::-webkit-scrollbar { height: 6px; }
.bracket-scroll::-webkit-scrollbar-thumb { background: var(--line-2); border-radius: 3px; }
.bracket-scroll::-webkit-scrollbar-track { background: transparent; }

.bracket {
  --card-h: 116px;
  --gap: 28px;
  --u: calc((var(--card-h) + var(--gap)) / 2);
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(238px, 1fr));
  grid-template-rows: repeat(6, var(--u));
  column-gap: clamp(44px, 6vw, 96px);
  min-width: 880px;
}
.b-col { display: contents; }
.b-col-head {
  position: sticky; top: 0; z-index: 4;
  grid-row: 1; align-self: start;
  display: flex; justify-content: space-between; align-items: baseline; gap: 10px;
  padding: 8px 2px; margin-bottom: 8px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, var(--bg) 68%, rgba(8, 9, 12, 0));
  -webkit-backdrop-filter: blur(4px); backdrop-filter: blur(4px);
  font-size: 12.5px; color: var(--text-3); letter-spacing: .02em;
}
.b-col-head b { font-weight: 500; color: var(--text-2); }
.b-col-head .ic { font-size: 14px; }
.b-lines { position: absolute; inset: 0; pointer-events: none; overflow: visible; z-index: 0; }
.b-lines path { fill: none; stroke: rgba(255, 255, 255, .16); stroke-width: 1; }
.b-lines path.on { stroke: var(--gold); stroke-opacity: .8; }
.b-lines path.live { stroke: var(--blood); stroke-opacity: .9; }

.match {
  grid-column: var(--col, 1);
  grid-row: var(--row, 1 / span 2);
  align-self: center;
  display: grid; grid-template-rows: auto auto auto;
  min-height: var(--card-h);
  border: 1px solid var(--line); border-radius: var(--r-md);
  background: linear-gradient(180deg, var(--card-2), var(--card));
  overflow: hidden; position: relative;
  transition: border-color .3s, box-shadow .5s, transform .3s var(--ease);
}
.match:hover { transform: translateY(-2px); }
.match-head {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding: 7px 12px; min-height: 28px;
  border-bottom: 1px solid var(--line);
  font-size: 11px; letter-spacing: .06em; text-transform: uppercase;
  color: var(--text-3); font-variant-numeric: tabular-nums;
}
.match-head .m-id { color: var(--text-3); }
.match-head .ic { font-size: 12px; }
.match.is-live { border-color: rgba(201, 79, 67, .6); box-shadow: 0 0 0 1px rgba(201, 79, 67, .2), 0 18px 44px -18px rgba(201, 79, 67, .55); }
.match.is-live .match-head { color: var(--blood-hi); }
.match.is-done { background: linear-gradient(180deg, #10131a, #0c0e13); }
.match.is-grand { border-color: rgba(201, 163, 90, .42); }
.match.is-grand .match-head { color: var(--gold); }
.match.is-champion { border-color: var(--gold); box-shadow: 0 0 70px -18px rgba(201, 163, 90, .6); }
.match.is-next { border-color: var(--line-3); }
.match.is-next::after {
  content: ''; position: absolute; inset: 0; pointer-events: none; border-radius: inherit;
  background: linear-gradient(105deg, transparent 35%, rgba(236, 214, 163, .12) 50%, transparent 65%);
  background-size: 260% 100%;
  animation: sheen 4.2s var(--ease) infinite;
}
@keyframes sheen { 0% { background-position: 140% 0; } 60%, 100% { background-position: -60% 0; } }

.slot {
  display: grid; grid-template-columns: 16px 1fr auto; align-items: center; gap: 10px;
  padding: 0 12px; min-height: 43px; position: relative;
}
.slot + .slot { border-top: 1px solid var(--line); }
.slot.is-clickable { cursor: pointer; }
.slot.is-clickable:hover { background: rgba(255, 255, 255, .035); }
.slot-seed { font-size: 11.5px; color: var(--text-3); font-variant-numeric: tabular-nums; }
.slot-name {
  font-size: 14.5px; font-weight: 500; min-width: 0;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.slot-side { display: inline-flex; align-items: center; gap: 8px; }
.slot-score {
  font-family: var(--display); font-weight: 400; font-size: 14px;
  color: var(--text-2); font-variant-numeric: tabular-nums;
  min-width: 18px; text-align: center;
}
.slot-info {
  width: 15px; height: 15px; border-radius: 50%; border: 1px solid var(--line-2);
  font-size: 9px; display: grid; place-items: center; color: var(--text-3);
  font-style: italic; flex: none; transition: border-color .2s, color .2s;
}
.slot.is-clickable:hover .slot-info { border-color: var(--gold); color: var(--gold-hi); }
.slot.is-winner .slot-name { color: var(--text); }
.slot.is-winner .slot-score { color: var(--gold-hi); }
.slot.is-winner::before {
  content: ''; position: absolute; left: 0; top: 9px; bottom: 9px; width: 2px;
  background: var(--gold); border-radius: 0 2px 2px 0;
}
.slot.is-loser .slot-name, .slot.is-loser .slot-seed, .slot.is-loser .slot-score { color: var(--text-3); }
.slot.is-tbd .slot-name { color: var(--text-3); font-weight: 400; }
.slot.is-tbd { cursor: default; }
.slot .vod { color: var(--text-3); display: inline-flex; }
.slot .vod:hover { color: var(--gold-hi); }

.b-legend { display: flex; flex-wrap: wrap; gap: 10px 24px; margin-top: 12px; font-size: 13px; color: var(--text-3); }
.b-legend span { display: inline-flex; align-items: center; }
.b-legend i { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 9px; }
.b-legend i.live { background: var(--blood); }
.b-legend i.up { border: 1px solid var(--text-2); }
.b-legend i.done { background: var(--gold); }
.b-legend .tz { margin-left: auto; }
.bracket-foot { display: flex; justify-content: space-between; align-items: center; gap: 16px; flex-wrap: wrap; }
.bracket-hint { display: none; font-size: 13px; color: var(--text-3); }
.footnote {
  margin-top: 34px; padding-left: 20px; border-left: 1px solid var(--gold);
  color: var(--text-2); font-size: 14px; max-width: 66ch;
}

/* Выбывшие */
.out-list { display: flex; flex-wrap: wrap; gap: 10px; }
.out-item {
  display: inline-flex; align-items: baseline; gap: 10px;
  padding: 9px 16px; border: 1px solid var(--line); border-radius: 999px;
  cursor: pointer; transition: border-color .2s, background .2s;
}
.out-item:hover { border-color: var(--line-2); background: rgba(255, 255, 255, .03); }
.out-item .name { font-size: 14px; color: var(--text-2); }
.out-item .meta { font-size: 12px; color: var(--text-3); }
.out-empty { color: var(--text-3); font-size: 14px; }

/* ==========================================================
   12. СПИСОК МАТЧЕЙ (расписание)
   ========================================================== */
.s-list { border-top: 1px solid var(--line); }
.s-row {
  display: grid; grid-template-columns: 132px 1fr auto; gap: 8px 28px;
  align-items: center; padding: 20px 6px; border-bottom: 1px solid var(--line);
  position: relative; transition: background .25s;
}
.s-row:hover { background: rgba(255, 255, 255, .018); }
.s-when { font-size: 13.5px; color: var(--text-2); font-variant-numeric: tabular-nums; }
.s-when b { display: block; font-family: var(--display); font-weight: 400; font-size: 17px; color: var(--gold-hi); margin-bottom: 3px; }
.s-when .tz { font-family: var(--ui); font-size: 11px; color: var(--text-3); margin-left: 5px; }
.s-when small { display: block; font-size: 12px; color: var(--text-3); margin-top: 4px; }
.s-when.is-tbd { color: var(--text-3); font-family: var(--ui); font-size: 14px; }
.s-teams { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; font-size: 17px; }
.s-teams .vs { color: var(--text-3); font-size: 12px; }
.s-teams .win { color: var(--gold-hi); }
.s-teams .lose { color: var(--text-3); }
.s-teams .sc { font-family: var(--display); font-weight: 400; font-size: 15px; color: var(--gold-hi); font-variant-numeric: tabular-nums; }
.s-side { display: flex; align-items: center; gap: 12px; white-space: nowrap; }
.s-tag { font-size: 12.5px; color: var(--text-3); white-space: nowrap; }
.s-tag.grand { color: var(--gold); }
.s-actions { display: flex; gap: 6px; }
.s-row.is-live { background: linear-gradient(90deg, rgba(201, 79, 67, .09), transparent 62%); }
.s-row.is-live::before {
  content: ''; position: absolute; left: 0; top: 14px; bottom: 14px; width: 2px;
  background: var(--blood); border-radius: 2px;
}
.s-row.done .s-when b { color: var(--text-3); }
.s-row.is-next { background: rgba(255, 255, 255, .022); }
.s-empty { padding: 34px 6px; color: var(--text-3); }

/* ==========================================================
   13. ТРАНСЛЯЦИЯ
   ========================================================== */
.stream-bar { display: flex; align-items: center; gap: 12px; font-size: 14px; color: var(--text-2); padding: 0 2px 14px; flex-wrap: wrap; }
.stream-bar .ic { font-size: 16px; }
.stream-bar a { margin-left: auto; }
.stream-frame {
  position: relative; aspect-ratio: 16 / 9; border-radius: var(--r-lg);
  overflow: hidden; border: 1px solid var(--line); background: #05060a;
}
.stream-frame > iframe, .stream-frame > #twitchEmbed { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
.stream-poster { position: absolute; inset: 0; overflow: hidden; }
.stream-poster::before {
  content: ''; position: absolute; inset: 0;
  background: url('/img/hero.webp') 74% 38% / cover no-repeat; opacity: .4;
}
.stream-poster::after {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse 62% 72% at 50% 48%, rgba(8, 9, 12, .45), rgba(8, 9, 12, .94));
}
.stream-inner {
  position: relative; z-index: 1; height: 100%;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; padding: 24px; gap: 14px;
}
.stream-inner .mark { width: 50px; height: 50px; border-radius: 50%; box-shadow: 0 0 0 1px var(--line-2); }
.stream-inner h3 { font-family: var(--display); font-weight: 300; font-size: clamp(19px, 2.5vw, 28px); line-height: 1.15; max-width: 22ch; }
.stream-inner p { color: var(--text-2); font-size: 14.5px; max-width: 46ch; }
.stream-inner .row { justify-content: center; }
.stream-play {
  display: inline-flex; align-items: center; gap: 12px; text-decoration: none;
  padding: 6px 22px 6px 6px; border-radius: 999px;
  border: 1px solid var(--line-2); background: rgba(255, 255, 255, .04);
  transition: border-color .25s, background .25s;
}
.stream-play:hover { border-color: var(--gold); background: rgba(201, 163, 90, .1); }
.stream-play .ring {
  width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center;
  background: linear-gradient(180deg, var(--gold-hi), var(--gold)); color: #15110a;
}
.stream-play .ring .ic { font-size: 18px; }
.stream-play b { font-weight: 500; }
.stream-play small { display: block; font-size: 12px; color: var(--text-3); }
.stream-next {
  margin-top: 4px; font-size: 13.5px; color: var(--text-3);
  display: inline-flex; align-items: center; gap: 10px; flex-wrap: wrap; justify-content: center;
}
.stream-next b { color: var(--text-2); font-weight: 500; }

/* ==========================================================
   14. ПОБЕДИТЕЛЬ
   ========================================================== */
.champ-banner {
  position: relative; overflow: hidden;
  display: grid; grid-template-columns: auto 1fr auto; gap: 18px 22px; align-items: center;
  padding: 20px 22px; border-radius: var(--r-lg);
  border: 1px solid rgba(201, 163, 90, .4);
  background:
    radial-gradient(ellipse 40% 160% at 0% 50%, rgba(201, 163, 90, .18), transparent 70%),
    linear-gradient(180deg, var(--card), var(--raise));
}
.champ-banner::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(100deg, transparent 40%, rgba(236, 214, 163, .14) 50%, transparent 60%);
  background-size: 240% 100%; animation: sheen 6s var(--ease) 1;
}
.champ-badge {
  width: 58px; height: 58px; border-radius: 16px; flex: none;
  display: grid; place-items: center; overflow: hidden;
  background: var(--card); border: 1px solid rgba(201, 163, 90, .5);
  box-shadow: 0 0 40px -12px rgba(201, 163, 90, .7);
}
.champ-badge img { width: 100%; height: 100%; object-fit: cover; }
.champ-badge .ph { font-family: var(--display); font-weight: 200; font-size: 24px; color: var(--gold-hi); }
.champ-banner .cb-label { font-size: 11.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--gold); margin-bottom: 6px; }
.champ-banner .cb-name { font-family: var(--display); font-weight: 400; font-size: clamp(20px, 2.6vw, 30px); line-height: 1.1; overflow-wrap: anywhere; }
.champ-banner .cb-sub { color: var(--text-3); font-size: 13px; margin-top: 6px; }
.champ-actions { display: flex; gap: 8px; flex-wrap: wrap; justify-content: flex-end; }

.champ-chip {
  position: fixed; left: 22px; bottom: 22px; z-index: 60;
  display: none; align-items: center; gap: 10px; padding: 10px 16px;
  border-radius: 999px; background: rgba(14, 17, 22, .92);
  border: 1px solid rgba(201, 163, 90, .5);
  -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
  font-size: 13.5px; cursor: pointer; text-decoration: none;
}
.champ-chip.visible { display: inline-flex; }
.champ-chip .ic { font-size: 16px; color: var(--gold); }
.champ-chip .name { color: var(--gold-hi); font-weight: 500; }
.champ-chip .x { color: var(--text-3); display: inline-flex; padding: 2px; }
.champ-chip .x:hover { color: var(--text); }

.podium { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px; }
.podium-item { border: 1px solid var(--line-2); border-radius: var(--r-md); padding: 16px 20px; background: var(--raise); }
.podium-item.place-1 { border-color: rgba(201, 163, 90, .55); background: linear-gradient(180deg, rgba(201, 163, 90, .1), var(--raise)); }
.podium-rank { font-size: 11.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--text-3); margin-bottom: 8px; }
.place-1 .podium-rank { color: var(--gold); }
.podium-name { font-family: var(--display); font-weight: 400; font-size: 16px; overflow-wrap: anywhere; }

/* ==========================================================
   15. ДИАЛОГИ
   ========================================================== */
.dlg {
  position: fixed; inset: 0; z-index: 150;
  background: rgba(4, 5, 7, .74);
  -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
  display: flex; align-items: center; justify-content: center; padding: 20px;
  opacity: 0; visibility: hidden; transition: opacity .3s, visibility .3s;
}
.dlg.active { opacity: 1; visibility: visible; }
.dlg-panel {
  position: relative; width: 100%; max-width: 460px;
  background: linear-gradient(180deg, var(--card), var(--raise));
  border: 1px solid var(--line-2); border-radius: var(--r-lg);
  padding: 26px; max-height: 90svh; overflow-y: auto;
  transform: translateY(14px) scale(.985); transition: transform .4s var(--ease);
}
.dlg.active .dlg-panel { transform: none; }
.dlg-close {
  position: absolute; top: 14px; right: 14px; width: 36px; height: 36px;
  border-radius: 50%; border: 1px solid var(--line); display: grid; place-items: center;
  transition: border-color .2s, background .2s;
}
.dlg-close:hover { border-color: var(--line-2); background: rgba(255, 255, 255, .05); }
.dlg-close .ic { font-size: 12px; }
.dlg-head { display: flex; align-items: center; gap: 18px; padding-right: 44px; margin-bottom: 24px; }
.dlg-logo {
  width: 60px; height: 60px; border-radius: var(--r-md); flex: none;
  border: 1px solid var(--line-2); background: var(--card);
  display: grid; place-items: center; overflow: hidden;
}
.dlg-logo img { width: 100%; height: 100%; object-fit: cover; }
.dlg-logo .ph { font-family: var(--display); font-weight: 300; font-size: 24px; color: var(--gold-hi); }
.dlg-head h2 { font-family: var(--display); font-weight: 400; font-size: 20px; line-height: 1.2; overflow-wrap: anywhere; }
.dlg-head .sub { color: var(--text-3); font-size: 13px; margin-top: 4px; }
.dlg-body { border-top: 1px solid var(--line); }
.dlg-row { display: flex; justify-content: space-between; gap: 16px; padding: 13px 2px; border-bottom: 1px solid var(--line); }
.dlg-row .k { font-weight: 500; overflow-wrap: anywhere; }
.dlg-row .v { color: var(--text-3); font-size: 13px; white-space: nowrap; }
.dlg-row.is-none { color: var(--text-3); font-size: 14px; }
.dlg-foot { margin-top: 22px; display: flex; gap: 10px; flex-wrap: wrap; }

/* Лайтбокс */
.lb {
  position: fixed; inset: 0; z-index: 200; background: rgba(4, 5, 7, .97);
  -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px);
  display: flex; align-items: center; justify-content: center;
  opacity: 0; visibility: hidden; transition: opacity .3s, visibility .3s;
}
.lb.active { opacity: 1; visibility: visible; }
.lb-frame { max-width: min(1200px, 92vw); max-height: 82vh; display: flex; flex-direction: column; align-items: center; gap: 16px; }
.lb-frame img { max-width: 100%; max-height: 74vh; border-radius: 10px; object-fit: contain; box-shadow: 0 30px 90px -20px rgba(0, 0, 0, .6); }
.lb-cap { color: var(--text-2); font-size: 14px; text-align: center; max-width: 60ch; min-height: 1.4em; }
.lb-close {
  position: absolute; top: 20px; right: 22px; width: 42px; height: 42px; border-radius: 50%;
  border: 1px solid var(--line-2); background: rgba(255, 255, 255, .04); display: grid; place-items: center;
}
.lb-arrow {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 48px; height: 48px; border-radius: 50%;
  border: 1px solid var(--line-2); background: rgba(255, 255, 255, .04);
  display: grid; place-items: center; transition: border-color .2s, background .2s;
}
.lb-arrow:hover { border-color: var(--gold); background: rgba(201, 163, 90, .1); }
.lb-prev { left: 18px; } .lb-next { right: 18px; }
.lb-count { position: absolute; top: 24px; left: 26px; font-size: 12.5px; color: var(--text-3); font-variant-numeric: tabular-nums; }

/* ==========================================================
   16. ГАЛЕРЕЯ
   ========================================================== */
.g-grid { display: grid; grid-template-columns: repeat(6, 1fr); grid-auto-rows: 130px; gap: 10px; }
.g-item { position: relative; overflow: hidden; border-radius: var(--r-md); cursor: zoom-in; grid-column: span 3; grid-row: span 2; background: var(--raise); }
.g-grid.n1 .g-item { grid-column: span 6; grid-row: span 4; }
.g-grid.n2 .g-item { grid-column: span 3; grid-row: span 3; }
.g-grid.n3 .g-item:first-child { grid-column: span 6; grid-row: span 3; }
.g-grid.n4 .g-item:nth-child(1) { grid-column: span 4; grid-row: span 3; }
.g-grid.n4 .g-item:nth-child(2) { grid-column: span 2; grid-row: span 3; }
.g-grid.n4 .g-item:nth-child(3), .g-grid.n4 .g-item:nth-child(4) { grid-column: span 3; grid-row: span 2; }
.g-item img { width: 100%; height: 100%; object-fit: cover; transition: transform .6s var(--ease-out); }
.g-item:hover img { transform: scale(1.05); }
.g-item .g-cap {
  position: absolute; left: 0; right: 0; bottom: 0; padding: 12px 14px;
  font-size: 12.5px; color: var(--text);
  background: linear-gradient(0deg, rgba(4, 5, 7, .88), transparent);
  opacity: 0; transition: opacity .25s;
}
.g-item:hover .g-cap { opacity: 1; }

/* ==========================================================
   17. АРХИВ / ТАБЛИЦЫ
   ========================================================== */
.tbl { width: 100%; border-collapse: collapse; font-size: 14px; }
.tbl caption { text-align: left; color: var(--text-3); font-size: 13px; padding-bottom: 12px; }
.tbl th, .tbl td { text-align: left; padding: 12px 10px; border-bottom: 1px solid var(--line); }
.tbl th { font-size: 11.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--text-3); font-weight: 500; }
.tbl td.n, .tbl th.n { text-align: right; font-variant-numeric: tabular-nums; }
.tbl tbody tr:hover { background: rgba(255, 255, 255, .02); }
.tbl .gold { color: var(--gold-hi); }
.tbl-scroll { overflow-x: auto; }

.season-list { display: grid; gap: 12px; }
.season-card {
  display: grid; grid-template-columns: 64px 1fr auto; gap: 8px 20px; align-items: center;
  padding: 16px 18px; border: 1px solid var(--line); border-radius: var(--r-md);
  background: var(--raise); text-decoration: none;
  transition: border-color .25s, transform .25s var(--ease), background .25s;
}
.season-card:hover { border-color: rgba(201, 163, 90, .45); transform: translateX(3px); }
.season-card .no { font-family: var(--display); font-weight: 200; font-size: 22px; color: var(--text-3); }
.season-card .nm { font-family: var(--display); font-weight: 400; font-size: 17px; }
.season-card .meta { color: var(--text-3); font-size: 13px; margin-top: 4px; }
.season-card .champ { color: var(--gold-hi); font-weight: 500; }
.season-card .go { color: var(--text-3); }

/* ==========================================================
   18. ПОЯВЛЕНИЕ + ДВИЖЕНИЕ
   ========================================================== */
.reveal { opacity: 0; transform: translateY(18px); transition: opacity .8s var(--ease), transform .8s var(--ease); }
.reveal.in { opacity: 1; transform: none; }
.reveal-d1 { transition-delay: .07s; } .reveal-d2 { transition-delay: .14s; }
.reveal-d3 { transition-delay: .21s; } .reveal-d4 { transition-delay: .28s; }

.to-top {
  position: fixed; right: 22px; bottom: 22px; z-index: 60;
  width: 44px; height: 44px; border-radius: 50%;
  background: rgba(14, 17, 22, .88); border: 1px solid var(--line-2);
  -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
  display: grid; place-items: center;
  opacity: 0; transform: translateY(10px); pointer-events: none;
  transition: opacity .3s, transform .3s var(--ease), border-color .2s;
}
.to-top.visible { opacity: 1; transform: none; pointer-events: auto; }
.to-top:hover { border-color: var(--gold); }
.to-top .ic { font-size: 16px; }

/* ==========================================================
   19. АДАПТИВ
   ========================================================== */
@media (max-width: 1020px) {
  .foot-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 900px) {
  .sec { padding: 72px 0; }
  .sec-head { grid-template-columns: 1fr; margin-bottom: 40px; }
  .sec-copy, .sec-aside { justify-self: start; }
  .champ-banner { grid-template-columns: auto 1fr; }
  .champ-actions { grid-column: 1 / -1; justify-content: flex-start; }
}
@media (max-width: 820px) {
  :root { --head-h: 58px; }
  body { font-size: 15.5px; }
  .wrap, .wrap-wide { padding: 0 20px; }
  .head-nav { display: none; }
  .burger { display: block; }
  .orn { gap: 12px; }
  .orn .ic { font-size: 18px; }
  .arena-compass { font-size: 150vw; right: -40%; top: -6%; opacity: .05; }

  /* Сетка на телефоне — вертикальная лента вместо горизонтального скролла */
  .bracket-scroll { overflow: visible; padding: 0; }
  .bracket {
    display: block; min-width: 0;
    --card-h: auto;
  }
  .bracket .b-lines { display: none; }
  .b-col-head { position: static; margin: 26px 0 12px; backdrop-filter: none; -webkit-backdrop-filter: none; background: none; }
  .b-col:first-child .b-col-head { margin-top: 0; }
  .b-match-list { display: grid; gap: 12px; }
  .match {
    position: static;
    grid-column: auto; grid-row: auto;
    min-height: 0; transform: none !important;
    animation: none !important;
  }
  .match.is-next::after { display: none; }
  .bracket-hint { display: none; }
  .s-row { grid-template-columns: 1fr; gap: 10px; padding: 18px 2px; }
  .s-when { display: flex; align-items: baseline; gap: 12px; }
  .s-when b { margin: 0; }
  .s-teams { font-size: 16px; }
  .s-side { justify-content: space-between; width: 100%; }
  .champ-chip { left: 14px; bottom: 14px; right: auto; padding: 9px 14px; }
  .foot-grid { grid-template-columns: 1fr; gap: 26px; }
  .g-grid, .g-grid.n1, .g-grid.n2, .g-grid.n3, .g-grid.n4 { grid-template-columns: repeat(2, 1fr); }
  .g-grid .g-item, .g-grid.n1 .g-item, .g-grid.n2 .g-item,
  .g-grid.n3 .g-item:first-child, .g-grid.n4 .g-item:nth-child(n) { grid-column: span 1; grid-row: span 2; }
  .stream-inner { padding: 16px; gap: 10px; }
  .stream-inner .mark { display: none; }
  .stream-inner p { font-size: 13px; margin-bottom: 4px; }
  .lb-arrow { width: 40px; height: 40px; }
  .lb-prev { left: 8px; } .lb-next { right: 8px; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
  .reveal { opacity: 1; transform: none; }
  .champ-banner::after, .match.is-next::after { display: none; }
  .ic-spin { animation: none; }
}

