<meta name="twitter:image" content="https://compassarena.ru/img/og-image.jpg">

<link rel="preload" href="/fonts/unbounded-cyrillic-wght-normal.woff2" as="font" type="font/woff2" crossorigin>
<link rel="preload" href="/fonts/onest-cyrillic-wght-normal.woff2" as="font" type="font/woff2" crossorigin>
<link rel="preload" as="image" href="/img/hero.webp" media="(min-width: 821px)" fetchpriority="high">
<link rel="preload" as="image" href="/img/hero-m.webp" media="(max-width: 820px)" fetchpriority="high">
<link rel="stylesheet" href="/site.css">

<style>
/* ==========================================================
   ГЛАВНАЯ: первый экран и блоки, которых нет на других страницах
   ========================================================== */
.hero {
  position: relative; overflow: hidden; display: flex; flex-direction: column;
  justify-content: flex-end; min-height: clamp(620px, 100svh, 900px);
}
body[data-phase="live"] .hero, body[data-phase="post"] .hero { min-height: clamp(560px, 84svh, 800px); }
.hero > .wrap { width: 100%; }
.hero-img { position: absolute; inset: 0; }
.hero-img img { width: 100%; height: 100%; object-fit: cover; object-position: 76% 42%; }
.hero-shade {
  position: absolute; inset: 0; pointer-events: none;
  background:
    linear-gradient(180deg, rgba(8,9,12,.66) 0%, rgba(8,9,12,0) 22%),
    linear-gradient(90deg, rgba(8,9,12,.9) 0%, rgba(8,9,12,.62) 32%, rgba(8,9,12,.12) 62%, rgba(8,9,12,0) 100%),
    linear-gradient(0deg, var(--bg) 0%, rgba(8,9,12,0) 36%);
}
#dust { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; opacity: .9; }
.hero-body { position: relative; z-index: 2; padding-top: calc(var(--head-h) + 30px); padding-bottom: 40px; }
.hero-kicker {
  display: inline-flex; align-items: center; gap: 12px;
  font-size: 13.5px; color: var(--text-2); margin-bottom: 22px;
}
.hero-kicker::before { content: ''; width: 34px; height: 1px; background: var(--gold); flex: none; }
.hero h1 { font-family: var(--display); font-weight: 300; font-size: clamp(29px, 4.1vw, 60px); line-height: 1.07; letter-spacing: -.025em; max-width: 15em; }
.hero h1 em { font-style: normal; color: var(--gold-hi); }
.hero .lede { margin-top: 24px; color: var(--text-2); font-size: clamp(15px, 1.25vw, 17.5px); max-width: 34em; }
.hero-cta { margin-top: 34px; display: flex; gap: 12px; flex-wrap: wrap; }

/* ---------- Статус под первым экраном ---------- */
#heroStatus { position: relative; z-index: 2; padding-bottom: 30px; }
.cd-inner {
  border-top: 1px solid var(--line-2); padding-top: 22px;
  display: grid; grid-template-columns: auto 1fr; gap: 18px 56px; align-items: end;
}
.cd-label { font-size: 13px; color: var(--text-2); line-height: 1.5; }
.cd-label b { display: block; font-weight: 400; color: var(--text); margin-top: 4px; font-variant-numeric: tabular-nums; }
.cd-nums { display: flex; gap: clamp(18px, 4vw, 54px); }
.cd-num { display: flex; flex-direction: column; }
.cd-num b {
  font-family: var(--display); font-weight: 200; letter-spacing: -.03em;
  font-size: clamp(32px, 4.6vw, 64px); line-height: 1; font-variant-numeric: tabular-nums;
}
.cd-num small { font-size: 12px; color: var(--text-3); margin-top: 8px; }
.cd-announce { grid-column: 1 / -1; color: var(--gold-hi); font-size: 14px; opacity: 0; height: 0; transition: opacity .5s; }
.cd-announce.visible { opacity: 1; height: auto; }
.cd-next { grid-column: 1 / -1; font-size: 14px; color: var(--text-2); display: flex; flex-wrap: wrap; gap: 4px 10px; align-items: baseline; }
.cd-next .k { color: var(--text-3); margin-right: 4px; }
.cd-next b { color: var(--text); font-weight: 500; }
.cd-next .t { color: var(--gold-hi); white-space: nowrap; }
.cd-track { grid-column: 1 / -1; height: 1px; background: var(--line); position: relative; margin-top: 6px; }
.cd-track i { position: absolute; left: 0; top: -1px; height: 3px; background: var(--gold); border-radius: 2px; transition: width 1s linear; }
.cd-caption { grid-column: 1 / -1; display: flex; justify-content: space-between; font-size: 12px; color: var(--text-3); font-variant-numeric: tabular-nums; }

/* Следующий матч / итог финала */
.nm-inner, .nm {
  border-top: 1px solid var(--line-2); padding-top: 20px;
  display: grid; grid-template-columns: 1fr auto; gap: 6px 40px; align-items: end;
}
.nm-label { grid-column: 1; display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--text-2); }
.nm-label .ic { font-size: 15px; color: var(--gold); }
.nm-teams {
  grid-column: 1; font-family: var(--display); font-weight: 300; letter-spacing: -.02em;
  font-size: clamp(19px, 2.6vw, 34px); line-height: 1.2; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 16px;
}
.nm-teams .vs { font-family: var(--ui); font-size: 13px; letter-spacing: 0; color: var(--text-3); }
.nm-teams .win { color: var(--gold-hi); }
.nm-meta { grid-column: 1; font-size: 14px; color: var(--text-2); }
.nm-count { grid-column: 2; grid-row: 1 / span 3; align-self: end; text-align: right; }
.nm-count b {
  display: block; font-family: var(--display); font-weight: 200; color: var(--gold-hi);
  font-size: clamp(26px, 3.6vw, 52px); line-height: 1; letter-spacing: -.02em; font-variant-numeric: tabular-nums;
}
.nm-count small { display: block; margin-top: 8px; font-size: 12px; color: var(--text-3); }

/* ---------- Ожидание эфира ---------- */
.note { border: 1px solid var(--line); border-radius: var(--r-lg); background: linear-gradient(180deg, var(--card), var(--raise)); overflow: hidden; }
.note-toggle { width: 100%; display: flex; align-items: center; gap: 16px; padding: 18px 22px; text-align: left; }
.note-toggle .t { font-family: var(--display); font-weight: 400; font-size: 15px; flex: 1; display: flex; align-items: center; gap: 12px; }
.note-time { font-size: 13.5px; color: var(--text-2); font-variant-numeric: tabular-nums; }
.note-time b { color: var(--text); font-weight: 500; }
.note-toggle .ic { color: var(--text-2); transition: transform .35s var(--ease); }
.note.open .note-toggle .ic { transform: rotate(180deg); }
.note-body { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .45s var(--ease); }
.note.open .note-body { grid-template-rows: 1fr; }
.note-body > div { overflow: hidden; }
.note-inner {
  padding: 20px 22px 22px; border-top: 1px solid var(--line);
  display: flex; gap: 18px 40px; justify-content: space-between; align-items: flex-end; flex-wrap: wrap;
}
.note-inner p { color: var(--text-2); max-width: 46ch; }
.note-inner .sign { color: var(--text-3); font-size: 14px; margin-top: 10px; }

/* ---------- Участники ---------- */
.team-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(232px, 1fr)); gap: 14px; }
.team-card {
  display: flex; flex-direction: column; gap: 10px; text-align: left;
  padding: 18px; border: 1px solid var(--line); border-radius: var(--r-md);
  background: linear-gradient(180deg, var(--card), var(--raise));
  transition: border-color .25s, transform .3s var(--ease), box-shadow .3s;
}
.team-card:hover { border-color: rgba(201,163,90,.42); transform: translateY(-3px); box-shadow: 0 20px 40px -26px rgba(0,0,0,.9); }
.tc-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.tc-logo {
  width: 52px; height: 52px; border-radius: var(--r-md); flex: none;
  border: 1px solid var(--line-2); background: var(--card);
  display: grid; place-items: center; overflow: hidden;
}
.tc-logo img { width: 100%; height: 100%; object-fit: cover; }
.tc-logo .ph { font-family: var(--display); font-weight: 300; font-size: 22px; color: var(--gold-hi); }
.tc-name { font-family: var(--display); font-weight: 400; font-size: 17px; overflow-wrap: anywhere; }
.tc-players { color: var(--text-3); font-size: 13px; line-height: 1.5; }
.tc-rec { color: var(--text-2); font-size: 12.5px; font-variant-numeric: tabular-nums; }

/* ---------- Следующий сезон ---------- */
.ns-grid { display: grid; grid-template-columns: 1.25fr .85fr; gap: 44px; align-items: start; }
.ns-when { display: inline-flex; align-items: center; gap: 10px; margin-top: 22px; color: var(--text-2); font-size: 14px; }
.ns-when .ic { color: var(--gold); font-size: 17px; }
.ns-when b { color: var(--text); }
.ns-side { display: grid; gap: 10px; }
.ns-row {
  display: flex; gap: 14px; align-items: center;
  padding: 14px 16px; border: 1px solid var(--line); border-radius: var(--r-md); background: var(--raise);
}
.ns-row .ic-holder {
  width: 38px; height: 38px; border-radius: 12px; flex: none;
  display: grid; place-items: center; font-size: 18px;
  background: rgba(201,163,90,.12); color: var(--gold-hi);
}
.ns-row b { display: block; font-weight: 500; font-size: 14.5px; }
.ns-row small { display: block; color: var(--text-3); font-size: 12.5px; }

/* ---------- Архив на главной ---------- */
.archive-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; flex-wrap: wrap; margin-bottom: 28px; }

@media (max-width: 900px) {
  .ns-grid { grid-template-columns: 1fr; gap: 28px; }
}
@media (max-width: 820px) {
  .hero { min-height: 100svh; }
  body[data-phase="live"] .hero, body[data-phase="post"] .hero { min-height: 78svh; }
  .hero-img img { object-position: 52% 22%; }
  .hero-shade {
    background:
      linear-gradient(180deg, rgba(8,9,12,.55) 0%, rgba(8,9,12,0) 20%),
      linear-gradient(0deg, var(--bg) 0%, rgba(8,9,12,.94) 32%, rgba(8,9,12,.22) 62%, rgba(8,9,12,0) 100%);
  }
  .hero-cta .btn { flex: 1; justify-content: center; }
  .cd-inner { grid-template-columns: 1fr; gap: 16px; }
  .cd-nums { justify-content: space-between; gap: 12px; }
  .nm-inner, .nm { grid-template-columns: 1fr; }
  .nm-count { grid-column: 1; grid-row: auto; text-align: left; margin-top: 12px; }
  .note-time { display: none; }
}
</style>
</head>
