<section class="sec" id="schedule">
  <div class="wrap">
    <div class="sec-head reveal">
      <div>
        <p class="kicker">Ближайшие и недавние матчи, время МСК</p>
        <h2 class="h2">Расписание</h2>
      </div>
      <div class="sec-aside">
        <a class="btn btn-ghost" href="/schedule.html">Все матчи и фильтры</a>
      </div>
    </div>
    <div id="schedulePreviewList" class="reveal"><div class="s-empty">Загрузка…</div></div>
  </div>
</section>

<!-- ============ АРХИВ ============ -->
<section class="sec" id="archiveSection" hidden>
  <div class="wrap">
    <div class="archive-head">
      <div>
        <p class="kicker">Прошлые турниры организации</p>
        <h2 class="h2">Архив</h2>
      </div>
      <a class="text-link" href="/history.html">Вся история</a>
    </div>
    <div class="season-list" id="archiveList"></div>
  </div>
</section>

<!-- ============ СЛЕДУЮЩИЙ СЕЗОН ============ -->
<section class="sec arena" id="next-season" hidden>
  <div class="wrap" id="nextSeasonBody"></div>
</section>

</main>

<footer class="site-foot">
  <div class="wrap">
    <div class="foot-grid">
      <div>
        <div class="foot-brand">
          <img src="/img/mark.webp" width="34" height="34" alt="" loading="lazy">
          <b>Compass <i>Arena</i></b>
        </div>
        <p class="foot-about">Организация турниров по Dota 2. Первый сезон — шесть команд и один трофей.</p>
      </div>
      <div class="foot-col">
        <h4>Турнир</h4>
        <a href="#bracket">Сетка</a>
        <a href="#teams">Участники</a>
        <a href="/schedule.html">Расписание</a>
        <a href="/rules.html">Правила</a>
      </div>
      <div class="foot-col">
        <h4>Организация</h4>
        <a href="/history.html">История</a>
        <a href="https://t.me/compassarenaa" target="_blank" rel="noopener">Telegram</a>
        <a href="https://www.twitch.tv/compassarena" target="_blank" rel="noopener">Twitch</a>
      </div>
      <div class="foot-col">
        <h4>Связь</h4>
        <a href="https://t.me/G0gg1a" target="_blank" rel="noopener">@G0gg1a</a>
        <a href="https://t.me/uuutt7" target="_blank" rel="noopener">@uuutt7</a>
        <a href="https://t.me/maushury" target="_blank" rel="noopener">@maushury</a>
      </div>
    </div>
    <div class="foot-bottom">
      <span>© <span id="year">2026</span> Compass Arena · Dota 2 — товарные знаки принадлежат Valve Corporation</span>
      <span><a href="/rules.html">Регламент</a> · <a href="/schedule.html">Расписание</a></span>
    </div>
  </div>
</footer>

<!-- ============ ДИАЛОГ КОМАНДЫ ============ -->
<div class="dlg" id="teamDialog" role="dialog" aria-modal="true" aria-labelledby="teamDialogName" aria-hidden="true">
  <div class="dlg-panel">
    <button class="dlg-close" data-dialog-close aria-label="Закрыть">
      <svg class="ic" aria-hidden="true"><use href="#i-close"></use></svg>
    </button>
    <div class="dlg-head">
      <div class="dlg-logo" id="teamDialogLogo"><span class="ph">?</span></div>
      <div>
        <h2 id="teamDialogName">Команда</h2>
        <div class="sub" id="teamDialogSub">Состав команды</div>
      </div>
    </div>
    <div class="dlg-body" id="teamDialogBody"></div>
    <div id="teamDialogStats"></div>
  </div>
</div>

<!-- Плашка чемпиона (появляется только после финала) -->
<div class="champ-chip" id="champChip" role="group" aria-label="Победитель турнира">
  <button type="button" class="row" style="gap:10px" data-chip-main>
    <svg class="ic" aria-hidden="true"><use href="#i-trophy"></use></svg>
    <span>Победитель — <span class="name" id="champChipName">—</span></span>
  </button>
  <button type="button" class="x" data-dismiss-chip aria-label="Скрыть плашку">
    <svg class="ic ic-14" aria-hidden="true"><use href="#i-close"></use></svg>
  </button>
</div>

<button class="to-top" id="toTop" aria-label="Наверх">
  <svg class="ic" aria-hidden="true"><use href="#i-arrow-up"></use></svg>
</button>

<script>document.getElementById('year').textContent = new Date().getFullYear();</script>
<script src="/assets/ca-data.js" defer></script>
<script src="/assets/ca-ui.js" defer></script>
<script src="/assets/ca-views.js" defer></script>
<script src="/assets/ca-bracket.js" defer></script>
<script src="/assets/ca-home.js" defer></script>
</body>
</html>
