{"content": "/* Smoke-тест публичных страниц в jsdom.
   Запуск: node .tmp-test/smoke.mjs   (из корня проекта) */
import fs from 'node:fs';
import path from 'node:path';
import { JSDOM } from 'jsdom';

const ROOT = process.cwd();
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8');

const TEAMS = [
  { id: 1, name: 'Team Spirit', players: [{ nick: 'Yatoro', role: 1 }, { nick: 'Larl', role: 2 }], logo: '' },
  { id: 2, name: 'Virtus.pro', players: ['Nightfall', 'gpk'], logo: '' },
  { id: 3, name: 'Team Liquid', players: [], logo: '' },
  { id: 4, name: 'OG', players: [], logo: '' },
  { id: 5, name: 'Gaimin Gladiators', players: [], logo: '' },
  { id: 6, name: 'BetBoom Team', players: [], logo: '' }
];
const M = (id, round, bracket, t1, t2, winner, s1, s2, vod) => ({
  id, round, bracket, team1: t1, team2: t2, winner, score1: s1, score2: s2, vod: vod || ''
});

const PRE = {
  tournament: { name: 'Compass Arena', game: 'Dota 2', format: 'Custom Bracket', matches: 'Bo3', dates: '26 сентября 2026' },
  teams: TEAMS,
  matches: [M(1, 1, 'upper', 1, 2), M(2, 1, 'upper', 3, 4), M(3, 1, 'upper', 5, 6), M(4, 2, 'upper'), M(5, 3, 'grand')],
  schedule: {},
  liveMatchId: null,
  tournamentStart: '2026-09-26T12:00:00+03:00',
  projectStart: '2026-01-01T00:00:00+03:00',
  history: []
};

const LIVE = {
  ...PRE,
  liveMatchId: 1,
  schedule: { 1: '2026-09-26T12:00', 2: '2026-09-26T15:00', 3: '2026-09-26T18:00' },
  matches: [M(1, 1, 'upper', 1, 2, null, 1, 0), M(2, 1, 'upper', 3, 4), M(3, 1, 'upper', 5, 6), M(4, 2, 'upper'), M(5, 3, 'grand')]
};

const POST = {
  ...PRE,
  liveMatchId: null,
  schedule: { 1: '2026-09-26T12:00', 2: '2026-09-26T15:00', 3: '2026-09-26T18:00', 4: '2026-09-27T14:00', 5: '2026-09-27T18:00' },
  matches: [
    M(1, 1, 'upper', 1, 2, 1, 2, 1, 'https://twitch.tv/videos/1'),
    M(2, 1, 'upper', 3, 4, 3, 2, 0),
    M(3, 1, 'upper', 5, 6, 5, 2, 1),
    M(4, 2, 'upper', 1, 3, 1, 2, 0),
    M(5, 3, 'grand', 1, 5, 1, 2, 1)
  ],
  nextSeason: { name: 'Compass Arena · второй сезон', date: '2027-01-15T12:00:00+03:00', note: 'Восемь команд.', url: 'https://t.me/compassarenaa' },
  history: [{
    id: 'ca-2026-09-26', name: 'Compass Arena #1', date: '26.09.2026', createdAt: '2026-09-27T00:00:00Z',
    format: 'Custom Bracket · Bo3', game: 'Dota 2', teams: TEAMS, matches: [], championId: 1, runnerUpId: 5,
    mvp: { teamId: 1, playerNick: 'Yatoro', note: 'Лучший игрок финала' }, photos: []
  }]
};

function makeDom(file, fixture) {
  let html = read(file);
  html = html.replace(/<script src="[^"]+"[^>]*><\/script>/g, '');
  const dom = new JSDOM(html, { url: 'https://compassarena.ru/' + file.replace('index.html', ''), pretendToBeVisual: true, runScripts: 'dangerously' });
  const w = dom.window;
  w.fetch = async () => ({ ok: true, json: async () => fixture });
  for (const f of ['ca-data.js', 'ca-ui.js', 'ca-views.js', 'ca-bracket.js', 'ca-home.js']) {
    try { w.eval(read('assets/' + f)); } catch (e) { throw new Error(f + ': ' + e.message); }
  }
  return dom;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let fails = 0;
function ok(cond, label, extra) {
  if (cond) console.log('  ok   ' + label);
  else { fails++; console.log('  FAIL ' + label + (extra ? ' → ' + extra : '')); }
}

/* ---------------- главная: pre ---------------- */
console.log('\nindex.html — состояние pre');
{
  const dom = makeDom('index.html', PRE);
  const { window } = dom;
  await sleep(120);
  const d = window.document;
  ok(d.body.dataset.phase === 'pre', 'фаза pre', d.body.dataset.phase);
  ok(!!d.querySelector('#heroStatus .cd'), 'отсчёт отрисован');
  ok(d.querySelector('#cdDays') && d.querySelector('#cdDays').textContent !== '--', 'дни заполнены', d.querySelector('#cdDays')?.textContent);
  ok(d.querySelectorAll('#bracketWrap .match').length === 5, 'пять карточек в сетке', d.querySelectorAll('#bracketWrap .match').length);
  ok((d.querySelector('#bracketWrap .match').getAttribute('style') || '').includes('grid-area'), 'карточка имеет grid-area');
  ok(d.querySelectorAll('#teamsGrid .team-card').length === 6, 'шесть карточек команд');
  ok(d.querySelectorAll('#schedulePreviewList .s-empty').length === 0, 'расписание отрисовано');
  ok(d.querySelector('#championSection').hidden === true, 'блок чемпиона скрыт');
  ok(d.querySelector('#streamWaiting').hidden === false, 'карточка ожидания эфира видна');
  ok(d.querySelector('#streamLive').hidden === true, 'плеер скрыт');
  ok(d.querySelector('#next-season').hidden === true, 'следующий сезон скрыт');
  ok(!!d.getElementById('ca-sprite'), 'спрайт иконок вставлен');
  ok(!!d.getElementById('ca-schema'), 'JSON-LD добавлен');
  ok(d.getElementById('phaseNote').textContent.includes('МСК'), 'подпись про МСК');
}

/* ---------------- главная: live ---------------- */
console.log('\nindex.html — состояние live');
{
  const dom = makeDom('index.html', LIVE);
  const { window } = dom;
  await sleep(120);
  const d = window.document;
  ok(d.body.dataset.phase === 'live', 'фаза live', d.body.dataset.phase);
  ok(!!d.querySelector('#heroStatus .nm'), 'блок следующего матча');
  ok(d.querySelector('#streamLive').hidden === false, 'плеер показан');
  ok(d.querySelector('#streamWaiting').hidden === true, 'ожидание скрыто');
  ok(d.querySelector('#streamPosterTitle').textContent.includes('включайтесь'), 'заголовок постера', d.querySelector('#streamPosterTitle').textContent);
  ok(d.querySelectorAll('#bracketWrap .match.is-live').length === 1, 'матч помечен live');
  ok(d.querySelector('#headProgress').style.getPropertyValue('--p') !== '', 'прогресс-бар заполнен');
}

/* ---------------- главная: post ---------------- */
console.log('\nindex.html — состояние post');
{
  const dom = makeDom('index.html', POST);
  const { window } = dom;
  await sleep(120);
