.page-hero::after {
  content: ''; position: absolute; inset: 0;
  background:
    linear-gradient(90deg, var(--bg) 6%, rgba(8,9,12,.55) 62%, rgba(8,9,12,.86) 100%),
    linear-gradient(0deg, var(--bg) 0%, rgba(8,9,12,0) 62%);
}
.page-hero .wrap { position: relative; z-index: 1; }
.page-hero h1 {
  font-family: var(--display); font-weight: 300;
