.next-card.is-live { border-color: rgba(201,79,67,.45); background: linear-gradient(90deg, rgba(201,79,67,.1), var(--raise) 60%); }
.next-card.is-empty { grid-template-columns: 1fr auto; }
.next-card .kicker { display: flex; align-items: center; gap: 9px; margin-bottom: 10px; }
.next-card.is-live .kicker { color: var(--blood-hi); }
.nc-teams {
  font-family: var(--display); font-weight: 300; letter-spacing: -.02em;
  font-size: clamp(20px, 2.6vw, 32px); line-height: 1.2;
}
.nc-teams .vs { font-family: var(--ui); font-size: 12.5px; letter-spacing: 0; color: var(--text-3); }
.nc-teams .sc { color: var(--gold-hi); font-variant-numeric: tabular-nums; }
.nc-meta { color: var(--text-2); font-size: 14px; margin-top: 8px; }
.nc-right { display: flex; flex-direction: column; align-items: flex-end; gap: 12px; }
.nc-count { text-align: right; }
.nc-count b {
  display: block; font-family: var(--display); font-weight: 200; color: var(--gold-hi);
  font-size: clamp(22px, 3vw, 38px); line-height: 1; font-variant-numeric: tabular-nums;
}
.nc-count b.live-num { color: var(--blood); letter-spacing: .04em; }
.nc-count small { display: block; margin-top: 6px; font-size: 12px; color: var(--text-3); }

/* Фильтры */
.filters {
  display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 40px;
  position: sticky; top: calc(var(--head-h) + 6px); z-index: 20; padding: 8px 0;
}
.chip-f {
  display: inline-flex; align-items: center; gap: 8px;
  height: 38px; padding: 0 16px; border-radius: 999px;
  border: 1px solid var(--line-2); background: rgba(8,9,12,.72);
  -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
  color: var(--text-2); font-size: 14px;
  transition: color .2s, background .2s, border-color .2s;
}
.chip-f:hover { color: var(--text); border-color: var(--line-3); }
.chip-f.active { background: var(--text); color: #0b0c0e; border-color: var(--text); }
.chip-n {
  font-size: 11.5px; font-variant-numeric: tabular-nums; color: var(--text-3);
  padding: 1px 7px; border-radius: 999px; background: rgba(255,255,255,.07);
}
.chip-f.active .chip-n { background: rgba(0,0,0,.14); color: #4b4d52; }

.day { margin-bottom: 46px; }
.day-title {
  font-family: var(--display); font-weight: 300;
  font-size: clamp(19px, 2.3vw, 27px); margin-bottom: 14px;
  display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap;
}
.day-title small { font-family: var(--ui); font-size: 13px; color: var(--text-3); }
.sched { padding: 8px 0 96px; }

@media (max-width: 820px) {
  .page-hero { padding-top: calc(var(--head-h) + 52px); }
  .next-card { grid-template-columns: 1fr; }
  .nc-right { align-items: flex-start; }
  .nc-count { text-align: left; }
  .filters { flex-wrap: nowrap; overflow-x: auto; margin: 0 -20px 30px; padding: 8px 20px; scrollbar-width: none; }
  .filters::-webkit-scrollbar { display: none; }
  .chip-f { flex: none; }
  .day-title small { display: block; margin: 0; }
}
