{"content": "/* Аудит: баланс скобок в CSS + ссылки на id из JS в HTML.
   Запуск: node .tmp-test/audit.mjs */
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8');
let fails = 0;

/* 1. Баланс фигурных скобок в CSS */
for (const f of ['site.css']) {
  const s = read(f);
  let depth = 0, line = 1, bad = null;
  for (const ch of s) {
    if (ch === '\n') line++;
    if (ch === '{') depth++;
    if (ch === '}') { depth--; if (depth < 0 && !bad) bad = line; }
  }
  const okBalance = depth === 0 && !bad;
  if (!okBalance) fails++;
  console.log((okBalance ? 'ok   ' : 'FAIL ') + f + ' — скобки (глубина ' + depth + (bad ? ', лишняя } в строке ' + bad : '') + ')');
}

/* 2. Ищет id, которые JS запрашивает, но которых нет в HTML */
const PAGES = {
  'index.html': ['assets/ca-home.js', 'assets/ca-ui.js', 'assets/ca-bracket.js', 'assets/ca-views.js'],
  'schedule.html': ['assets/ca-schedule.js', 'assets/ca-ui.js', 'assets/ca-views.js'],
  'rules.html': ['assets/ca-rules.js', 'assets/ca-ui.js'],
  '404.html': ['assets/ca-ui.js']
};

for (const [page, scripts] of Object.entries(PAGES)) {
  if (!fs.existsSync(path.join(ROOT, page))) { console.log('skip ' + page + ' (нет файла)'); continue; }
  const html = read(page);
  const ids = new Set(Array.from(html.matchAll(/id="([^"]+)"/g), (m) => m[1]));
  const used = new Set();
  for (const f of scripts) {
    const js = read(f);
    for (const m of js.matchAll(/getElementById\('([^']+)'\)/g)) used.add(m[1]);
  }
  const missing = Array.from(used).filter((x) => !ids.has(x));
  if (missing.length) fails++;
  console.log((missing.length ? 'FAIL ' : 'ok   ') + page + ' — id из JS на месте' + (missing.length ? ': нет ' + missing.join(', ') : ''));
}

/* 3. Ссылки в разметке на несуществующие локальные файлы */
for (const page of Object.keys(PAGES)) {
  if (!fs.existsSync(path.join(ROOT, page))) continue;
  const html = read(page);
  const refs = Array.from(html.matchAll(/(?:src|href)="(\/[^"#?]+)"/g), (m) => m[1]);
  const bad = refs.filter((r) => !fs.existsSync(path.join(ROOT, r.replace(/^\//, ''))));
  if (bad.length) fails++;
  console.log((bad.length ? 'FAIL ' : 'ok   ') + page + ' — локальные ссылки' + (bad.length ? ': нет ' + bad.join(', ') : ''));
}

process.exit(fails ? 1 : 0);
", "file_path": ".tmp-test\audit.mjs"}

