  const id = ++seq;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify(sessionId ? { id, method, params, sessionId } : { id, method, params }));
  });
}
function waitEvent(method, sessionId, timeout = 15000) {
  return new Promise((resolve, reject) => {
    const w = { method, sessionId, resolve };
    waiters.push(w);
    setTimeout(() => {
      const i = waiters.indexOf(w);
      if (i >= 0) { waiters.splice(i, 1); reject(new Error('таймаут ' + method)); }
    }, timeout);
  });
}

const { targetId } = await send('Target.createTarget', { url: 'about:blank' });
const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });

await send('Page.enable', {}, sessionId);
await send('Runtime.enable', {}, sessionId);
await send('Emulation.setDeviceMetricsOverride', {
  width, height: mobile ? 844 : 900, deviceScaleFactor: 1, mobile
}, sessionId);

const loaded = waitEvent('Page.loadEventFired', sessionId);
await send('Page.navigate', { url }, sessionId);
await loaded;
await sleep(2200);

const metrics = await send('Page.getLayoutMetrics', {}, sessionId);
const size = metrics.cssContentSize || metrics.contentSize;
const height = Math.min(Math.ceil(size.height), 12000);
const shot = await send('Page.captureScreenshot', {
  format: 'png', captureBeyondViewport: true,
  clip: { x: 0, y: 0, width: Math.ceil(size.width), height, scale: 1 }
}, sessionId);
fs.writeFileSync(out, Buffer.from(shot.data, 'base64'));
console.log('saved ' + out + ' (' + Math.ceil(size.width) + 'x' + height + ')');

ws.close();
chrome.kill();
process.exit(0);
", "file_path": ".tmp-test\shot.mjs"}

