{"content": "/* Диагностика: доступен ли локальный сервер и поднимается ли Chrome. */
import { spawn } from 'node:child_process';
import path from 'node:path';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

try {
  const r = await fetch('http://127.0.0.1:4173/');
  console.log('server:', r.status);
} catch (e) {
  console.log('server error:', e.message);
}

const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const userDir = path.join(process.cwd(), '.tmp-test', 'chrome-profile2');
const PORT = 9444;
const child = spawn(CHROME, [
  '--headless=new', '--disable-gpu', '--no-sandbox', '--disable-breakpad',
  '--remote-debugging-port=' + PORT, '--user-data-dir=' + userDir, 'about:blank'
], { stdio: 'ignore' });
child.on('error', (e) => console.log('spawn error:', e.message));
child.on('exit', (code, sig) => console.log('chrome exit:', code, sig));

for (let i = 0; i < 20; i++) {
  await sleep(500);
  try {
    const r = await fetch('http://127.0.0.1:' + PORT + '/json/version');
    console.log('chrome ready after', (i + 1) * 500, 'ms:', (await r.json())['Browser']);
    child.kill();
    process.exit(0);
  } catch (e) { /* ещё не поднялся */ }
}
console.log('chrome НЕ ответил на порту', PORT);
child.kill();
process.exit(1);
", "file_path": ".tmp-test\diag.mjs"}

