import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const userDir = path.join(process.cwd(), '.tmp-test', 'chrome-profile3');
const logFile = path.join(process.cwd(), '.tmp-test', 'chrome.log');
fs.mkdirSync(userDir, { recursive: true });

const args = [
  '--headless=new', '--no-sandbox', '--no-zygote', '--single-process',
  '--disable-gpu', '--disable-breakpad', '--disable-crash-reporter',
  '--enable-logging', '--v=1', '--log-file=' + logFile,
  '--remote-debugging-port=9555', '--user-data-dir=' + userDir,
  '--dump-dom', 'data:text/html,<h1>hi</h1>'
];
const child = spawn(CHROME, args, { stdio: 'ignore' });
child.on('exit', (code, sig) => console.log('exit:', code, sig));
await sleep(6000);
child.kill();
console.log('log exists:', fs.existsSync(logFile));
if (fs.existsSync(logFile)) console.log(fs.readFileSync(logFile, 'utf8').split('\n').slice(0, 25).join('\n'));
", "file_path": ".tmp-test\diag2.mjs"}

