import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const PORT = 9777;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const JOBS = [
  { url: 'http://127.0.0.1:4173/', out: 'home-post.png', width: 1440 },
  { url: 'http://127.0.0.1:4173/', out: 'home-post-mobile.png', width: 412, mobile: true },
  { url: 'http://127.0.0.1:4174/', out: 'home-pre.png', width: 1440 },
  { url: 'http://127.0.0.1:4175/', out: 'home-live.png', width: 1440 },
  { url: 'http://127.0.0.1:4173/schedule.html', out: 'schedule-post.png', width: 1440 },
  { url: 'http://127.0.0.1:4175/schedule.html', out: 'schedule-live.png', width: 1440 },
  { url: 'http://127.0.0.1:4173/history.html', out: 'history-post.png', width: 1440 },
  { url: 'http://127.0.0.1:4173/rules.html', out: 'rules.png', width: 1440 }
];

const profile = path.join(process.cwd(), '.tmp-test', 'chrome-profile');
fs.mkdirSync(profile, { recursive: true });

const chrome = spawn(CHROME, [
  '--headless=new', '--disable-gpu', '--no-first-run', '--no-default-browser-check',
  '--no-sandbox', '--disable-breakpad', '--disable-crash-reporter', '--disable-dev-shm-usage',
  '--hide-scrollbars', '--force-color-profile=srgb', '--font-render-hinting=none',
  '--remote-debugging-port=' + PORT, '--user-data-dir=' + profile, 'about:blank'
], { stdio: 'ignore' });

async function waitChrome() {
  for (let i = 0; i < 80; i++) {
    try {
      const r = await fetch('http://127.0.0.1:' + PORT + '/json/version');
      if (r.ok) return await r.json();
    } catch (e) {}
    await sleep(250);
  }
  throw new Error('Chrome не поднялся');
}

const version = await waitChrome();
const ws = new WebSocket(version.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

let seq = 0;
const pending = new Map();
const waiters = [];
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
  } else if (msg.method) {
    for (let i = waiters.length - 1; i >= 0; i--) {
      if (waiters[i].method === msg.method && (!waiters[i].sessionId || waiters[i].sessionId === msg.sessionId)) {
        waiters[i].resolve(msg.params);
        waiters.splice(i, 1);
      }
    }
  }
};
function send(method, params = {}, sessionId) {
  const id = ++seq;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify(sessionId ? { id, method, params, sessionId } : { id, method, params }));
  });
}
function waitEvent(method, sessionId, timeout = 20000) {
  return new Promise((resolve, reject) => {
    const w = { method, sessionId, resolve };
    waiters.push(w);
    setTimeout(() => {
      const i = waiters.indexOf(w);
      if (i >= 0) { waiters.splice(i, 1); reject(new Error('таймаут ' + method)); }
    }, timeout);
  });
}

const { targetId } = await send('Target.createTarget', { url: 'about:blank' });
const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });
await send('Page.enable', {}, sessionId);
await send('Runtime.enable', {}, sessionId);

for (const job of JOBS) {
  await send('Emulation.setDeviceMetricsOverride', {
    width: job.width, height: job.mobile ? 844 : 900, deviceScaleFactor: 1, mobile: !!job.mobile
  }, sessionId);
  const loaded = waitEvent('Page.loadEventFired', sessionId);
  await send('Page.navigate', { url: job.url }, sessionId);
  await loaded;
  await sleep(2000);
  const metrics = await send('Page.getLayoutMetrics', {}, sessionId);
  const size = metrics.cssContentSize || metrics.contentSize;
  const height = Math.min(Math.ceil(size.height), 12000);
  const shot = await send('Page.captureScreenshot', {
    format: 'png', captureBeyondViewport: true,
    clip: { x: 0, y: 0, width: Math.ceil(size.width), height, scale: 1 }
  }, sessionId);
  const file = path.join(process.cwd(), '.tmp-test', job.out);
  fs.writeFileSync(file, Buffer.from(shot.data, 'base64'));
  console.log('saved ' + job.out + '  ' + Math.ceil(size.width) + 'x' + height + ' (' + Math.round(fs.statSync(file).size / 1024) + ' КБ)');
}

ws.close();
chrome.kill();
process.exit(0);
