{"file_path": "poasalj1.z23.html", "new_string": "function saveData(force) {
    if (!DATA_READY) {
        showToast('⏳ Данные ещё не загружены — сохранение отменено (обновите страницу)');
        return Promise.resolve(false);
    }
    /* Пустая история поверх непустой — это почти всегда потеря архива.
       Требуем явного подтверждения (или force из кнопки «Очистить архив»). */
    if (!force && HISTORY.length === 0 && SERVER_HISTORY_N > 0) {
        var sure = confirm('⚠️ Вы сохраняете ПУСТУЮ историю.\n\nЭто удалит из архива ' + SERVER_HISTORY_N + ' ' +
            pluralT(SERVER_HISTORY_N) + ' вместе с чемпионами, MVP и фото.\n\nПродолжить?');
        if (!sure) {
            showToast('💾 Сохранение отменено — архив на месте');
            return Promise.resolve(false);
        }
    }
    updateMatchLinks();
    var pw = ensurePassword();
    // Собираем payload: DATA + history отдельным полем
    var payload = Object.assign({}, DATA, { history: HISTORY, clearHistory: !!force });

    return fetch('/api/save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password: pw, data: payload })
    }).then(function(res) {
        if (res.status === 403) {
            ADMIN_PW = null;
            showToast('⛔ Неверный пароль — экран возвращён к серверным данным');
            return loadData().then(renderEverything);
        }
        if (res.status === 429) {
            return res.text().then(function(msg) {
                showToast('🚫 ' + msg);
                return loadData().then(renderEverything);
            });
        }
        if (!res.ok) throw new Error('save failed: ' + res.status);
        return res.json().catch(function() { return {}; });
    }).then(function(out) {
        if (out && out.historyKept) {
            showToast('⚠️ Сервер сохранил прежний архив — чтобы очистить его, используйте «Очистить архив»');
            return loadData().then(renderEverything);
        }
        SERVER_HISTORY_N = HISTORY.length;
        return true;
    }).catch(function(err) {
        console.warn('Не удалось сохранить', err);
        showToast('⚠️ Не удалось сохранить — экран возвращён к серверным данным');
        return loadData().then(renderEverything);
    });
}
