   не только кнопке «Зафиксировать», но и сбросу сезона / удалению команд. */
function buildSnapshot() {
    updateMatchLinks();
    var grand = getMatch(5);
    var now = new Date();
    var id = 'ca-' + now.getFullYear() + '-' + pad2(now.getMonth() + 1) + '-' + pad2(now.getDate()) + '-' + now.getTime();
    var dateStr = DATA.tournament.dates || (pad2(now.getDate()) + '.' + pad2(now.getMonth() + 1) + '.' + now.getFullYear());

    return {
        id: id,
        name: DATA.tournament.name || 'Compass Arena',
        date: dateStr,
        format: (DATA.tournament.format || 'Custom Bracket') + ' · ' + (DATA.tournament.matches || 'Bo3'),
        game: DATA.tournament.game || 'Dota 2',
        createdAt: now.toISOString(),
        // Снапшот данных на момент фиксации
        teams: JSON.parse(JSON.stringify(DATA.teams || [])),
        matches: JSON.parse(JSON.stringify(DATA.matches || [])),
        championId: grand ? grand.winner : null,
        runnerUpId: grand ? getLoser(grand) : null,
        mvp: { teamId: null, playerNick: '', note: '' },
        photos: []
    };
}

/* Добавить текущий турнир в архив без открытия модалки (для сброса/удаления команд) */
function archiveCurrentSeason() {
    var snapshot = buildSnapshot();
    HISTORY.unshift(snapshot);
    if (HISTORY.length > 20) HISTORY = HISTORY.slice(-20);
    return snapshot;
}

/* Турнир выглядит завершённым: есть победитель финала или сыграны все матчи */
function tournamentLooksFinished() {
    updateMatchLinks();
    var grand = getMatch(5);
    if (grand && grand.winner) return true;
    for (var i = 0; i < DATA.matches.length; i++) if (DATA.matches[i].winner) return true;
    return false;
}

/* Есть ли уже снапшот текущего турнира в архиве */
function currentSeasonArchived() {
    for (var i = 0; i < HISTORY.length; i++) {
        var h = HISTORY[i];
        if (!h || !Array.isArray(h.matches)) continue;
        var sameMatch = false;
        for (var j = 0; j < DATA.matches.length; j++) {
            var cur = DATA.matches[j];
            var old = null;
            for (var k = 0; k < h.matches.length; k++) if (h.matches[k] && h.matches[k].id === cur.id) old = h.matches[k];
            if (old && cur.winner && old.winner === cur.winner && cur.id === 5) { sameMatch = true; break; }
        }
        if (sameMatch) return true;
    }
    return false;
}

/* Предложить зафиксировать завершённый турнир перед тем, как его разрушить.
   Возвращает true, если можно продолжать действие. */
function offerArchiveBefore(action) {
    if (!tournamentLooksFinished() || currentSeasonArchived()) return true;
    var yes = confirm('Турнир выглядит завершённым.\n\nЗафиксировать его в историю перед тем, как ' + action + '?\n\n' +
        '«ОК» — сначала сохраним главу в архив, «Отмена» — продолжим без сохранения (результаты будут потеряны).');
    if (yes) {
        var snap = archiveCurrentSeason();
        showToast('📌 Турнир добавлен в историю — открыт как «' + (snap.name || 'Compass Arena') + '»');
    }
    return true;
}

function snapshotCurrentTournament() {
    updateMatchLinks();
    var grand = getMatch(5);
    if (!grand || !grand.winner) {
        if (!confirm('В финале (M5) ещё нет победителя. Зафиксировать всё равно? (снапшот будет без чемпиона)')) return;
    }

    var snapshot = archiveCurrentSeason();
    saveData();
    renderHistory();
    showToast('📌 Турнир зафиксирован в истории. Открой ✏️ чтобы добавить MVP и фото.');

    setTimeout(function() { openHistoryModal(snapshot.id); }, 300);
}
