{"content": "import fs from 'node:fs';
import path from 'node:path';
import { JSDOM } from 'jsdom';

const ROOT = process.cwd();
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const SLOTS = [1, 2, 3, 4, 5, 6].map((id) => ({ id, name: 'Слот ' + id, logo: '', players: [] }));
const M = (id, round, bracket, t1, t2, winner, s1, s2) => ({ id, round, bracket, team1: t1, team2: t2, winner, score1: s1, score2: s2 });
const DATA = {
  tournament: { name: 'Compass Arena', game: 'Dota 2', format: 'Custom Bracket', matches: 'Bo3', dates: 'осень 2031' },
  teams: SLOTS,
  matches: [M(1, 1, 'upper', 1, 2, 1, 2, 1), M(2, 1, 'upper', 3, 4, 3, 2, 0), M(3, 1, 'upper', 5, 6, 5, 2, 1),
    M(4, 2, 'upper', 1, 3, 1, 2, 0), M(5, 3, 'grand', 1, 5, 1, 2, 1)],
  schedule: {}, liveMatchId: null, tournamentStart: '2031-09-26T12:00:00+03:00', history: []
};

const html = read('index.html').replace(/<script src="[^"]+"[^>]*><\/script>/g, '');
const dom = new JSDOM(html, { url: 'https://compassarena.ru/', pretendToBeVisual: true, runScripts: 'dangerously' });
const w = dom.window;
w.fetch = async () => ({ ok: true, json: async () => DATA });
for (const f of ['ca-data.js', 'ca-ui.js', 'ca-views.js', 'ca-bracket.js', 'ca-home.js']) w.eval(read('assets/' + f));
await sleep(250);

const body = w.document.body.innerHTML;
const idx = [];
let i = -1;
while ((i = body.indexOf('Слот', i + 1)) !== -1) idx.push(i);
console.log('вхождений «Слот»:', idx.length);
idx.slice(0, 6).forEach((p) => console.log('\n---\n' + body.slice(Math.max(0, p - 220), p + 90).replace(/\s+/g, ' ')));
", "file_path": "tests\_debug-slots.mjs"}

