{"file_path": "poasalj1.z23.html", "new_string": "/* ============================================================
   ФИКСАЦИЯ ТУРНИРА В ИСТОРИЮ
   ------------------------------------------------------------
   Жёсткие правила, чтобы главы не плодились и не расползались:
   1. У сезона есть отпечаток (fingerprint) — состав команд и все
      результаты матчей. Он пишется в главу при фиксации.
   2. Сезон фиксируется ОДИН раз: id главы запоминается в
      DATA.archivedSnapshotId. Пока он там — автоподсказок больше нет.
   3. Если после фиксации результаты изменились, глава помечается
      «устарела» и её можно обновить, не теряя MVP и фото.
   4. Дубликаты глав (частичные копии одного турнира) находятся по
      вложенности результатов и убираются одной кнопкой.
   ============================================================ */
function seasonFingerprint() {
    updateMatchLinks();
    var parts = [];
    for (var i = 0; i < (DATA.matches || []).length; i++) {
        var m = DATA.matches[i] || {};
        parts.push([m.id, m.team1 || '', m.team2 || '', m.winner || '',
            m.score1 == null ? '' : m.score1, m.score2 == null ? '' : m.score2].join(':'));
    }
    var teams = (DATA.teams || []).map(function(t) { return t.id + '=' + (t.name || ''); }).sort();
    return parts.join('|') + '#' + teams.join(',');
}

/* Отпечаток записи архива: у новых глав он сохранён, у старых считаем на месте */
function chapterFingerprint(h) {
