    var container = document.getElementById('historyList');
    var countEl = document.getElementById('historyCount');
    if (!container) return;

    var dupes = findDuplicates();
    var dupeCount = Object.keys(dupes).length;
    if (countEl) {
        countEl.textContent = HISTORY.length + ' ' + pluralT(HISTORY.length) +
            (dupeCount ? ' · дубликатов: ' + dupeCount : '');
    }

    renderHistoryStatus(dupes);

    if (HISTORY.length === 0) {
        container.innerHTML = '<div style="color:#5f6773;font-size:13px;text-align:center;padding:20px;font-style:italic;">Пока ни одного турнира в истории</div>';
        return;
    }

    /* Номера турниров — как на сайте: по хронологии, первый турнир = №1 */
    var chrono = HISTORY.slice().sort(function(a, b) {
        return (new Date(a.createdAt || 0).getTime()) - (new Date(b.createdAt || 0).getTime());
    });
    var seasonOf = {};
    for (var s = 0; s < chrono.length; s++) seasonOf[chrono[s].id] = s + 1;

    /* А в списке админки — свежие сверху */
    var sorted = chrono.slice().reverse();

    container.innerHTML = '';
    for (var i = 0; i < sorted.length; i++) {
        var t = sorted[i];
        var season = seasonOf[t.id] || (sorted.length - i);
        var champ = null;
        if (t.teams) {
            for (var k = 0; k < t.teams.length; k++) {
                if (t.teams[k].id === t.championId) { champ = t.teams[k]; break; }
            }
        }

        var logoHtml = '';
        if (champ && champ.logo) logoHtml = '<img src="' + champ.logo + '" alt="">';
        else if (champ && champ.name) logoHtml = '<span class="placeholder">' + champ.name.charAt(0).toUpperCase() + '</span>';
        else logoHtml = '<span class="placeholder">?</span>';

        var decided = 0;
        var matches = t.matches || [];
        for (var d = 0; d < matches.length; d++) if (matches[d] && matches[d].winner) decided++;

        var mvpText = (t.mvp && t.mvp.playerNick) ? (' · MVP: ' + t.mvp.playerNick) : '';
        var photosText = (t.photos && t.photos.length) ? (' · ' + t.photos.length + ' фото') : '';

        var badges = '';
        if (DATA.archivedSnapshotId === t.id) {
            badges += '<span class="h-badge">текущий сезон</span>';
            if (chapterIsStale()) badges += '<span class="h-badge warn">результаты изменились — обнови главу</span>';
        }
        if (dupes[t.id]) {
            badges += '<span class="h-badge warn">дубликат главы №' + (seasonOf[dupes[t.id]] || '?') + '</span>';
        }

        var div = document.createElement('div');
        div.className = 'history-item' + (dupes[t.id] ? ' is-dupe' : '');
        div.innerHTML =
            '<div class="h-logo">' + logoHtml + '</div>' +
            '<div class="h-info">' +
                '<div class="h-name"><span class="h-no">Турнир №' + season + '</span> ' + escapeHtml(t.name) + badges + '</div>' +
                '<div class="h-meta">' + escapeHtml(t.date || '') + ' · Победитель: <span class="champ">' + escapeHtml(champ ? champ.name : '—') + '</span>' +
                    ' · серий: ' + decided + escapeHtml(mvpText + photosText) + '</div>' +
            '</div>' +
            '<div class="h-actions">' +
                '<a class="btn btn-sm" href="/history.html#ch-' + encodeURIComponent(t.id) + '" target="_blank" rel="noopener" title="Открыть главу на сайте">🔗</a>' +
                '<button class="btn btn-sm" onclick="openHistoryModal(\'' + escapeHtml(t.id) + '\')" title="Редактировать главу">✏️</button>' +
                '<button class="btn btn-sm btn-danger" onclick="deleteHistoryItem(\'' + escapeHtml(t.id) + '\')" title="Удалить главу">✕</button>' +
