/* Строка состояния фиксации: что с текущим сезоном и что с дублями */
function renderHistoryStatus(dupes) {
    var box = document.getElementById('historyStatus');
    if (!box) return;
    var archived = currentSeasonArchived();
    var h = archivedChapter();
