        /* Импорт заменяет и текущий турнир, и архив — поэтому спрашиваем про архив явно */
        HISTORY = fileHistory;
        var forceHistory = false;
        if (!fileHistory.length && SERVER_HISTORY_N > 0) {
            var keep = confirm('В файле НЕТ истории турниров, а на сервере сейчас ' + SERVER_HISTORY_N + ' ' + pluralT(SERVER_HISTORY_N) + '.\n\n' +
                '«ОК» — оставить серверный архив как есть.\n' +
                '«Отмена» — очистить архив (в файле истории нет).');
