                /* оставляем серверный архив: подтянем его с сервера после сохранения */
                forceHistory = false;
            } else {
                forceHistory = true;
            }
        }

        DATA = data;
        if (!DATA.archivedSnapshotId) DATA.archivedSnapshotId = null;
        DATA_READY = true;                    /* данные пришли из файла, сохранять можно */
        ARCHIVE_PROMPT_DECLINED = false;

        var imported = JSON.parse(JSON.stringify(HISTORY));
