/* Список других глав для слияния (кроме той, что открыта) */
function renderMergeSelect(currentId) {
    var sel = document.getElementById('histMergeSelect');
    if (!sel) return;
    var chrono = HISTORY.slice().sort(function(a, b) {
        return (new Date(a.createdAt || 0).getTime()) - (new Date(b.createdAt || 0).getTime());
    });
    var opts = '<option value="">— выбери главу —</option>';
    for (var i = 0; i < chrono.length; i++) {
        var h = chrono[i];
        if (!h || h.id === currentId) continue;
        var decided = 0;
        for (var k = 0; k < (h.matches || []).length; k++) if (h.matches[k] && h.matches[k].winner) decided++;
        opts += '<option value="' + escapeHtml(h.id) + '">№' + (i + 1) + ' · ' + escapeHtml(h.name || '') +
            ' · ' + escapeHtml(h.date || '') + ' · серий: ' + decided +
            ((h.photos && h.photos.length) ? ' · фото: ' + h.photos.length : '') + '</option>';
    }
    sel.innerHTML = opts;
