    var sel = document.getElementById('histMergeSelect');
    var srcId = sel ? sel.value : '';
    if (!srcId) { showToast('Выбери главу для слияния'); return; }

    var target = null, source = null;
    for (var i = 0; i < HISTORY.length; i++) {
        if (HISTORY[i].id === EDITING_HISTORY_ID) target = HISTORY[i];
        if (HISTORY[i].id === srcId) source = HISTORY[i];
    }
    if (!target || !source) { showToast('Главы не найдены'); return; }

    var srcDecided = 0;
    for (var d = 0; d < (source.matches || []).length; d++) if (source.matches[d] && source.matches[d].winner) srcDecided++;
    if (!confirm('Слить главу «' + (source.date || '') + '» (серий: ' + srcDecided + ') в текущую «' + (target.date || '') + '»?\n\n' +
        'Выбранная глава будет удалена, всё ценное перенесётся сюда.')) return;

    /* Команды: объединяем по id, заполняем то, чего нет */
    var teamsById = {};
    target.teams = target.teams || [];
    for (var t = 0; t < target.teams.length; t++) teamsById[target.teams[t].id] = target.teams[t];
    for (var s = 0; s < (source.teams || []).length; s++) {
        var st = source.teams[s];
        if (!st) continue;
        if (!teamsById[st.id]) { target.teams.push(JSON.parse(JSON.stringify(st))); teamsById[st.id] = st; }
        else if ((!teamsById[st.id].name || /^слот/i.test(teamsById[st.id].name)) && st.name) {
            teamsById[st.id].name = st.name;
            teamsById[st.id].players = teamsById[st.id].players && teamsById[st.id].players.length ? teamsById[st.id].players : st.players;
        }
    }

    /* Матчи: объединяем по id, приоритет — заполненные поля */
    var byId = {};
    target.matches = target.matches || [];
    for (var m = 0; m < target.matches.length; m++) byId[target.matches[m].id] = target.matches[m];
    for (var n = 0; n < (source.matches || []).length; n++) {
        var sm = source.matches[n];
        if (!sm) continue;
        var tm = byId[sm.id];
        if (!tm) { target.matches.push(JSON.parse(JSON.stringify(sm))); continue; }
        if (sm.team1 && !tm.team1) tm.team1 = sm.team1;
        if (sm.team2 && !tm.team2) tm.team2 = sm.team2;
        if (sm.winner && !tm.winner) { tm.winner = sm.winner; tm.score1 = sm.score1; tm.score2 = sm.score2; }
        if (sm.vod && !tm.vod) tm.vod = sm.vod;
    }

