      const retryAfter = (data && data.parameters && data.parameters.retry_after) || 2;
      await sleep(retryAfter * 1000);
      return apiForm(env, method, formData, attempt + 1);
    }
    throw new TelegramError(method, code, description);
  }
  return data.result;
