   ============================================================ */

import { sendMessage, answerCallbackQuery, inlineKeyboard } from '../lib/telegram.js';
import { getState } from '../lib/db.js';
import { esc } from '../lib/esc.js';
import { disciplinesListLabel } from '../lib/domain.js';

