  const state = await getState(env, ctx.userId);

  await answerCallbackQuery(env, query.id, { text: 'Раздел регистрации появится на ШАГЕ 3' });

  await sendMessage(env, ctx.chatId,
    '🚧 <b>Регистрация в разработке</b>\n\n' +
    `Нажата кнопка: <code>${esc(ctx.data)}</code>\n` +
    `Дисциплины: ${esc(disciplinesListLabel())}\n` +
    `Текущий шаг: <code>${esc(state.step || 'нет')}</code>\n\n` +
