{"content": "/* ============================================================
   Модерация заявок: /leads, кнопки approve / reject
   ------------------------------------------------------------
   ⚠️ ЗАГЛУШКА ЭТАПА 1–2.
   Логика (список заявок, карточка заявки, approve/reject
   с причиной и уведомлением автора) появится на ШАГЕ 4.
   Сейчас команда уже проверяет права админа и читает D1 —
   это позволяет проверить связку «воркер ↔ база» сразу после деплоя.
   ============================================================ */

import { sendMessage, answerCallbackQuery, inlineKeyboard } from '../lib/telegram.js';
import { countLeads, pendingBreakdown, countUsers } from '../lib/db.js';
import { esc, plural } from '../lib/esc.js';
import { disciplineLabel, leadTypeLabel } from '../lib/domain.js';

export const commands = ['leads'];
export const callbackPrefixes = ['mod'];

export async function handleCommand(env, message, ctx) {
  if (ctx.cmd !== 'leads') return false;

  if (!ctx.isAdmin) {
    await sendMessage(env, ctx.chatId, '⛔ Команда доступна только организаторам турнира.');
    return true;
  }

  const counts = await countLeads(env);
  const breakdown = await pendingBreakdown(env);
  const users = await countUsers(env);

  const lines = [
    '🛠 <b>Модерация заявок</b>',
    '',
    `Пользователей в боте: <b>${users}</b>`,
    `На модерации: <b>${counts.pending}</b>`,
    `Одобрено: <b>${counts.approved}</b>`,
    `Отклонено: <b>${counts.rejected}</b>`
  ];

  if (breakdown.length) {
    lines.push('', '<b>Ожидают решения</b>');
    for (const row of breakdown) {
      lines.push(`• ${esc(disciplineLabel(row.discipline))} · ${esc(leadTypeLabel(row.type))}: <b>${row.n}</b>`);
    }
  } else {
    lines.push('', 'Ожидающих заявок нет.');
  }

  lines.push('', 'Полный список с кнопками «Одобрить / Отклонить» подключается на ШАГЕ 4.');

  await sendMessage(env, ctx.chatId, lines.join('\n'), {
    keyboard: inlineKeyboard([[{ text: '🏠 В меню', data: 'act:menu' }]])
  });
  return true;
}

export async function handleCallback(env, query, ctx) {
  if (!ctx.isAdmin) {
    await answerCallbackQuery(env, query.id, { text: 'Недостаточно прав', showAlert: true });
    return true;
  }
  await answerCallbackQuery(env, query.id, { text: 'Модерация появится на ШАГЕ 4' });
  return true;
}

export async function handleText() {
  return false;
}

export async function handlePhoto() {
  return false;
}
