let failed = 0;

function ok(condition, label, extra) {
  if (condition) {
    passed++;
    console.log('  ok   ' + label);
  } else {
    failed++;
    console.log('  FAIL ' + label + (extra === undefined ? '' : ' → ' + JSON.stringify(extra)));
  }
}

/* ============================================================
   Поддельный Bot API: перехватываем fetch
   ============================================================ */
const calls = [];
const originalFetch = globalThis.fetch;

function mockTelegram(handlers = {}) {
  calls.length = 0;
  globalThis.fetch = async (url, init = {}) => {
    const method = String(url).split('/').pop().split('?')[0];
    let body = null;
    if (typeof init.body === 'string') {
      try { body = JSON.parse(init.body); } catch { body = init.body; }
    }
    calls.push({ method, body, url: String(url) });
    const custom = handlers[method];
    const result = custom ? await custom(body) : { message_id: 1 };
    return { ok: true, status: 200, json: async () => ({ ok: true, result }) };
  };
}

