  const statement = (sql) => ({
    bind(...params) {
      return makeStatement(sql, params);
    },
    first: () => makeStatement(sql, []).first(),
    all: () => makeStatement(sql, []).all(),
    run: () => makeStatement(sql, []).run()
  });

  function makeStatement(sql, params) {
    return {
      async first() {
        if (/FROM leads WHERE telegram_id/.test(sql)) return lastLeadAt ? { created_at: lastLeadAt } : null;
        if (/COUNT\(\*\) AS leads/.test(sql)) return { leads: pending + approved + rejected };
        if (/COUNT\(\*\) AS n FROM users/.test(sql)) return { n: users };
        if (/FROM settings WHERE key/.test(sql)) return { value: 'Compass Arena Season 2' };
        if (/FROM users WHERE telegram_id/.test(sql)) return null;
        if (/FROM states WHERE telegram_id/.test(sql)) return null;
        if (/FROM leads WHERE id/.test(sql)) return null;
        return null;
      },
      async all() {
        if (/GROUP BY status/.test(sql)) {
          return {
            results: [
              { status: 'pending', n: pending },
              { status: 'approved', n: approved },
              { status: 'rejected', n: rejected }
            ]
          };
