/* ============================================================
   Регистрация: команда / свободный агент / заявка игрока
   ------------------------------------------------------------
   ⚠️ ЗАГЛУШКА ЭТАПА 1–2.
   Интерфейс объявлен окончательно, логика шагов появится на ШАГЕ 3
   (см. план работ). Сейчас обработчик только отвечает на нажатия,
   чтобы можно было проверить webhook, клавиатуры и маршрутизацию.
   ============================================================ */

import { sendMessage, answerCallbackQuery, inlineKeyboard } from '../lib/telegram.js';
