  ok(/Логотип: — не загружен/.test(last()), 'в карточке отмечено отсутствие логотипа');

  await tap(env, USER, 'reg:confirm');
  ok(/отправлена на модерацию/.test(last()), 'заявка отправлена на модерацию');

  const lead = fake._db.lastLead();
