/* ============================================================
   Поддельная D1: минимальный набор запросов, которые делает бот
   ============================================================ */
function fakeDb({ pending = 2, approved = 3, rejected = 1, users = 5, lastLeadMinutesAgo = null } = {}) {
  const lastLeadAt = lastLeadMinutesAgo == null
    ? null
    : new Date(Date.now() - lastLeadMinutesAgo * 60_000).toISOString().slice(0, 19).replace('T', ' ');

  const statement = (sql) => ({
    bind(...params) {
      return makeStatement(sql, params);
    },
    first: () => makeStatement(sql, []).first(),
    all: () => makeStatement(sql, []).all(),
    run: () => makeStatement(sql, []).run()
  });

  function makeStatement(sql, params) {
    return {
      async first() {
        if (/FROM leads WHERE telegram_id/.test(sql)) return lastLeadAt ? { created_at: lastLeadAt } : null;
        if (/COUNT\(\*\) AS leads/.test(sql)) return { leads: pending + approved + rejected };
        if (/COUNT\(\*\) AS n FROM users/.test(sql)) return { n: users };
        if (/FROM settings WHERE key/.test(sql)) {
          const map = {
            registration_open: '1',
            current_discipline: 'dota2',
            current_tournament: 'Compass Arena Season 2'
          };
          const value = map[params[0]];
          return value === undefined ? null : { value };
        }
        if (/FROM users WHERE telegram_id/.test(sql)) return null;
        if (/FROM states WHERE telegram_id/.test(sql)) return null;
        if (/FROM leads WHERE id/.test(sql)) return null;
        return null;
      },
      async all() {
        if (/GROUP BY status/.test(sql)) {
          return {
            results: [
              { status: 'pending', n: pending },
              { status: 'approved', n: approved },
              { status: 'rejected', n: rejected }
            ]
          };
        }
        if (/status = 'pending'/.test(sql) && /GROUP BY discipline/.test(sql)) {
          return { results: [{ discipline: 'dota2', type: 'team', n: pending }] };
        }
        return { results: [] };
      },
      async run() {
        return { success: true, meta: { last_row_id: 1 } };
      }
    };
  }

  return { DB: { prepare: (sql) => statement(sql) } };
}

