import { sendMessage, editMessageText, sendPhoto, inlineKeyboard } from './telegram.js';

/** Собираем inline-клавиатуру (короткий алиас) */
export const kb = inlineKeyboard;

/** Кнопка «в меню» */
export const menuRow = { text: '🏠 В меню', data: 'act:menu' };

