export function buildTeamsDocument({ discipline, teams, freeAgents, exportedAt }) {
  const list = (teams || []).slice().sort((a, b) => a.id - b.id);  // по возрастанию id заявки
  return {
    type: 'teams',
    version: EXPORT_VERSION,
    exportedAt: exportedAt || new Date().toISOString(),
    discipline,
    teams: list.map((lead, index) => ({
      id: `team_${index + 1}`,
      num: index + 1,
      name: lead.payload.name || '',
      logo: lead.payload.logo || '',
      logoOversized: Boolean(lead.payload.logoOversized),
      captainNick: lead.payload.captainNick || '',
      captainTelegramId: lead.payload.captainTelegramId || lead.telegram_id || null,
      players: (lead.payload.players || []).map((p) => ({ nick: p.nick, role: p.role, roleLabel: p.roleLabel }))
    })),
    freeAgents: (freeAgents || []).map((lead) => {
      const p = lead.payload || {};
      const isPlayer = p.type === 'player';
      return {
        nick: p.nick || '',
        role: p.role || 0,
        roleLabel: p.roleLabel || '',
        rank: p.rank || '',
        note: isPlayer ? (p.teamName ? `Сейчас играет в «${p.teamName}»` : '') : (p.note || ''),
        telegramId: lead.telegram_id || null,
        type: isPlayer ? 'player' : 'looking_for_team'
      };
    })
  };
}

export function buildSettingsDocument({ discipline, tournamentName, exportedAt }) {
