async function doExport(env, ctx, discChoice, target) {
  // проверка: нет команд → отказ
  const counts = await countsFor(env, discChoice);
  if (target !== 'settings' && counts.teams === 0) { → «Нет команд для экспорта»; return; }
  const disciplines = counts.disciplines;
  const jobs = [];
  for (const d of disciplines) {
    const { teams, agents } = await collectExport(env, d);
    if (target !== 'settings') jobs.push({ kind: 'teams', discipline: d, doc: buildTeamsDocument({discipline: d, teams, freeAgents: agents, exportedAt}), filename: `teams_${dateStamp()}_${d}.json` });
    if (target !== 'teams') jobs.push({ kind: 'settings', discipline: d, doc: buildSettingsDocument({discipline: d, tournamentName, exportedAt}), filename: `settings_${dateStamp()}_${d}.json` });
  }
  await answerCallbackQuery(toast 'Отправляю файлы');
  for (let i = 0; i < jobs.length; i++) {
    const job = jobs[i];
    const caption = `Файл ${i+1}/${jobs.length}: ${disciplineLabel(job.discipline)} ${job.kind === 'teams' ? 'команды' : 'настройки'}`;
    await sendDocument(env, ctx.chatId, { filename: job.filename, content: JSON.stringify(job.doc, null, 2), contentType: 'application/json' }, { caption: esc(caption) });
  }
  await sendMessage(env, ctx.chatId, `📤 Экспорт готов: ${jobs.length} ${plural(jobs.length,'файл','файла','файлов')} отправлены...`, { keyboard: kb([[menuRow]]) });
}
```
