    `📤 <b>Экспорт готов:</b> ${sent} ${plural(sent, 'файл', 'файла', 'файлов')} отправлено.\n\n` +
    'Загрузи их в админке сайта → раздел «Импорт из бота».',
    { keyboard: kb([[menuRow]]) });
  return true;
}

export async function handleText() {
