function botNormalizeTeams(doc, strategy) {
    var teams = [];
    var seen = {};
    var duplicates = [];
    for (var i = 0; i < doc.teams.length; i++) {
        var t = doc.teams[i];
        var key = String(t.name || '').trim().toLowerCase();
        if (seen[key] !== undefined) {
            duplicates.push(t.name);
            if (strategy === 'skip') continue;       // оставляем первую
            teams[seen[key]] = t;                    // «заменить» — оставляем последнюю
            continue;
        }
        seen[key] = teams.length;
        teams.push(t);
    }
    // присваиваем последовательные id 1..N и оставляем только нужные поля
    var out = [];
    for (var j = 0; j < teams.length; j++) {
        var src = teams[j];
