            players: src.players.map(function (p) { return { nick: String(p.nick).trim(), role: parseInt(p.role, 10), roleLabel: p.roleLabel || '' }; })
        });
    }
    return { teams: out, duplicates: duplicates, agents: botNormalizeAgents(doc.freeAgents) };
}
