function botDuplicates(teams) {
    var seen = {}, out = [];
    for (var i = 0; i < teams.length; i++) {
        var t = teams[i] || {};
        var key = String(t.name || '').trim().toLowerCase();
        if (!key) continue;
        if (seen[key] === undefined) { seen[key] = { name: String(t.name).trim(), count: 1, positions: [i + 1] }; out.push(seen[key]); }
        else { seen[key].count++; seen[key].positions.push(i + 1); }
    }
    return out.filter(function (d) { return d.count > 1; });
}
```
