        html += '<button class="btn ' + (list[i].cls || '') + '" onclick="' + list[i].action + '">' + list[i].label + '</button>';
    }
    box.innerHTML = html;
}
function botFileSummary() {
    var plan = botPlan();
    if (!plan) return '';
    var doc = plan.doc;
    var info = botDisciplineInfo(doc.discipline);
    var oversized = 0;
    for (var i = 0; i < plan.teams.length; i++) if (plan.teams[i].logoOversized) oversized++;

    return '<div class="bd-row"><span class="bd-key">Файл</span><span class="bd-val">' + escapeHtml(plan.fileName) + '</span></div>' +
        '<div class="bd-row"><span class="bd-key">Тип</span><span class="bd-val">' + (plan.kind === 'teams' ? 'команды (teams)' : 'настройки (settings)') + '</span></div>' +
        '<div class="bd-row"><span class="bd-key">Дисциплина</span><span class="bd-val">' + escapeHtml(info.label) + '</span></div>' +
        (plan.kind === 'teams'
            ? '<div class="bd-row"><span class="bd-key">Команд в файле</span><span class="bd-val">' + plan.teams.length + '</span></div>' +
              '<div class="bd-row"><span class="bd-key">Свободных агентов</span><span class="bd-val">' + plan.agents.length + '</span></div>' +
              (oversized ? '<div class="bd-row"><span class="bd-key">Логотипы</span><span class="bd-val">⚠️ у ' + oversized + ' команд логотип больше 200 КБ</span></div>' : '')
            : '');
}

function botOpenStep(step) {
    BOT_STEP = step;
    var title = document.getElementById('botModalTitle');
    var body = document.getElementById('botModalBody');
    if (!title || !body) return;

    if (step === 'duplicates') {
        var plan = botPlan();
        var rows = '';
        for (var i = 0; i < plan.duplicates.length; i++) {
            var d = plan.duplicates[i];
            rows += '<div class="bot-item"><div class="bi-info"><span class="bi-name">' + escapeHtml(d.name) + '</span>' +
                '<span class="bi-meta">повторяется ' + d.count + ' раза · команды №' + d.positions.join(', ') + '</span></div></div>';
        }
        title.textContent = '🔁 Повторяющиеся названия';
        body.innerHTML = '<div class="bd-warn">⚠️ В файле есть команды с одинаковыми названиями.</div>' +
            '<div>Оставить последнюю версию (заменить) или первую (пропустить повторы)?</div>' +
            '<div class="bot-list">' + rows + '</div>';
        botSetActions([
            { label: '🔁 Заменить', action: "botConfirmDuplicates('replace')", cls: 'btn-primary' },
            { label: '⏭ Пропустить', action: "botConfirmDuplicates('skip')" },
            { label: '◀ Отмена', action: 'botImportCancel()' }
        ]);
    } else if (step === 'teams-replace') {
        title.textContent = '📥 Импорт команд';
        body.innerHTML = '<div class="bd-warn">⚠️ Импорт заменит список команд полностью.</div>' +
            '<div>Сейчас в админке команд: ' + (Array.isArray(DATA.teams) ? DATA.teams.length : 0) + '.</div>' +
            '<div class="bot-details">' + botFileSummary() + '</div>';
        botSetActions([
            { label: '✅ Продолжить', action: 'botStepToMatches()', cls: 'btn-primary' },
            { label: '◀ Отмена', action: 'botImportCancel()' }
        ]);
    } else if (step === 'matches-reset') {
        var played = 0;
        for (var k = 0; k < DATA.matches.length; k++) if (DATA.matches[k] && DATA.matches[k].winner) played++;
        title.textContent = '⚠️ Сброс сетки';
        body.innerHTML = '<div class="bd-warn">⚠️ Импорт команд сбросит текущую сетку (матчи и расписание).' +
            ' Все пары нужно будет расставить заново.</div>' +
            '<div>Сейчас в сетке матчей с результатом: ' + played + '.</div>' +
            '<div class="bot-details">' + botFileSummary() + '</div>';
        botSetActions([
            { label: '✅ Продолжить', action: 'botApplyTeams()', cls: 'btn-primary' },
            { label: '◀ Отмена', action: 'botImportCancel()' }
        ]);
    } else if (step === 'settings') {
        var t = (BOT_PENDING && BOT_PENDING.doc ? BOT_PENDING.doc.tournament : {}) || {};
        var rows2 = '';
        var pairs = [
            ['Название', DATA.tournament.name, t.name],
            ['Игра', DATA.tournament.game, t.game],
            ['Формат', DATA.tournament.format, t.format],
            ['Матчи', DATA.tournament.matches, t.matches],
            ['Даты', DATA.tournament.dates, t.dates]
        ];
        for (var m = 0; m < pairs.length; m++) {
            rows2 += '<div class="bd-row"><span class="bd-key">' + pairs[m][0] + '</span><span class="bd-val">' +
                escapeHtml(pairs[m][1] || '—') + ' → <b>' + escapeHtml(pairs[m][2] || '—') + '</b></span></div>';
        }
        title.textContent = '⚙️ Настройки турнира';
        body.innerHTML = 'Из файла <b>' + escapeHtml(BOT_PENDING.fileName) + '</b> будут применены настройки турнира.' +
            '<div>Команды и сетка матчей не изменятся.</div>' +
            '<div class="bot-details" style="margin-top:10px;">' + rows2 + '</div>';
        botSetActions([
            { label: '✅ Применить', action: 'botApplySettings()', cls: 'btn-primary' },
            { label: '◀ Отмена', action: 'botImportCancel()' }
        ]);
    }

    document.getElementById('botModal').classList.add('active');
}

function botConfirmDuplicates(strategy) {
    if (!BOT_PENDING) return;
    BOT_PENDING.strategy = strategy;
    botPlan();
    botOpenStep('teams-replace');
}
function botStepToMatches() {
    if (!BOT_PENDING) return;
    botOpenStep('matches-reset');
}

/* ---------- 6. Применение ---------- */
function botApplyTeams() {
    var plan = botPlan();
    if (!plan || plan.kind !== 'teams') return;

    offerArchiveBefore('импортировать команды из бота');

    var oversized = 0;
    for (var i = 0; i < plan.teams.length; i++) if (plan.teams[i].logoOversized) oversized++;

    var gameKey = botGameKey(DATA.tournament.game);
    var fileKey = botGameKey(plan.doc.discipline);
    var mismatch = fileKey && gameKey && fileKey !== gameKey;

    DATA.teams = plan.teams;
    DATA.freeAgents = plan.agents;
    /* Матчи под старые команды не подходят — сетку и расписание сбрасываем */
    DATA.matches = getDefaultData().matches;
    DATA.schedule = {};
    DATA.liveMatchId = null;
    DATA.archivedSnapshotId = null;

    var fileName = plan.fileName;
    var teamsN = plan.teams.length;
    var agentsN = plan.agents.length;

    botCloseModal();
    BOT_PENDING = null;
    BOT_STEP = null;
    showToast('📥 Импортировано команд: ' + teamsN);
    saveData().then(function () {
        renderEverything();
        botShowImportResult('teams', fileName, teamsN, agentsN, oversized, mismatch ? plan.doc.discipline : null);
    });
}

function botApplySettings() {
    if (!BOT_PENDING || BOT_PENDING.kind !== 'settings') return;
    var t = BOT_PENDING.doc.tournament || {};
    if (t.name) DATA.tournament.name = String(t.name);
    if (t.game) DATA.tournament.game = String(t.game);
    if (t.format) DATA.tournament.format = String(t.format);
    if (t.matches) DATA.tournament.matches = String(t.matches);
    if (t.dates) DATA.tournament.dates = String(t.dates);

    var fileName = BOT_PENDING.fileName;
    botCloseModal();
    BOT_PENDING = null;
    BOT_STEP = null;
    showToast('⚙️ Настройки турнира обновлены');
    saveData().then(function () {
        renderEverything();
        botShowImportResult('settings', fileName, 0, 0, 0, null);
    });
}

function botShowImportResult(kind, fileName, teamsN, agentsN, oversized, mismatchedDiscipline) {
    var html = '<div class="as-text">' + (kind === 'teams'
        ? '✅ Импортировано команд: <b>' + teamsN + '</b> (файл «' + escapeHtml(fileName) + '»). ' +
          'Сетка сброшена — расставь пары в разделе «Матчи».'
        : '✅ Настройки турнира обновлены (файл «' + escapeHtml(fileName) + '»).') + '</div>';

    if (agentsN > 0) {
        html += '<div class="as-text">🎯 Найдено свободных агентов: <b>' + agentsN + '</b>.</div>';
    }
    if (oversized > 0) {
        html += '<div class="as-text">⚠️ У ' + oversized + ' команд логотип больше 200 КБ — на сайте они могут грузиться дольше.</div>';
    }
    if (mismatchedDiscipline) {
        html += '<div class="as-text">ℹ️ В файле дисциплина ' + escapeHtml(botDisciplineInfo(mismatchedDiscipline).label) +
            ', а в настройках сайта — ' + escapeHtml(DATA.tournament.game || '—') + '. Импортируй ещё файл настроек, если нужно поменять игру.</div>';
    }

    var actions = '';
    if (agentsN > 0) actions += '<button class="btn btn-sm" onclick="switchTab(\'agents\')">Посмотреть</button>';
    actions += '<button class="btn btn-sm" onclick="switchTab(\'teams\')">К командам</button>';
    html += '<div class="as-actions">' + actions + '</div>';

    botShowImportStatus('ok', html);
}

/* Что сейчас лежит в админке (перед импортом полезно посмотреть) */
function botShowCurrentState() {
    var teams = Array.isArray(DATA.teams) ? DATA.teams.length : 0;
    var agents = Array.isArray(DATA.freeAgents) ? DATA.freeAgents.length : 0;
    var played = 0;
    for (var i = 0; i < DATA.matches.length; i++) if (DATA.matches[i] && DATA.matches[i].winner) played++;
    var logoBytes = 0;
    for (var j = 0; j < DATA.teams.length; j++) logoBytes += base64Size(DATA.teams[j].logo);

    botShowImportStatus('neutral', '<div class="as-text">Сейчас: команд <b>' + teams + '</b>, свободных агентов <b>' + agents +
        '</b>, матчей с результатом <b>' + played + '</b>, логотипы занимают <b>' + formatBytes(logoBytes) + '</b>.</div>');
}

/* ---------- 7. Вкладка «Свободные агенты» ---------- */
function renderAgents() {
    var list = document.getElementById('agentList');
    var counter = document.getElementById('agentsCount');
    if (!list) return;
    var agents = Array.isArray(DATA.freeAgents) ? DATA.freeAgents : [];
