        list.innerHTML = '<div class="photos-empty">Свободных агентов пока нет. Загрузи файл команд из бота на вкладке «📥 Импорт из бота».</div>';
        return;
    }
    for (var i = 0; i < agents.length; i++) {
        var a = agents[i] || {};
        var info = botDisciplineInfo((BOT_PENDING && BOT_PENDING.doc && BOT_PENDING.doc.discipline) || DATA.tournament.game === 'CS:GO' ? 'csgo' : 'dota2');
        var roleText = a.roleLabel || (info.roles && info.roles[a.role]) || '';
        var meta = [];
        if (roleText) meta.push(roleText);
        if (a.rank) meta.push('ранг: ' + a.rank);
        if (a.note) meta.push(a.note);

        var div = document.createElement('div');
        div.className = 'bot-item';
        div.innerHTML =
            '<div class="bi-info">' +
                '<span class="bi-name">' + escapeHtml(a.nick || '—') + ' ' +
                    '<span class="bot-badge' + (a.type === 'player' ? ' warn' : '') + '">' +
                    (a.type === 'player' ? 'заявка игрока' : 'ищет команду') + '</span></span>' +
                '<span class="bi-meta">' + escapeHtml(meta.join(' · ')) + '</span>' +
            '</div>' +
            '<div class="bi-actions">' +
                (a.telegramId ? '<a href="tg://user?id=' + encodeURIComponent(String(a.telegramId)) + '">написать</a>' : '') +
            '</div>';
        list.appendChild(div);
    }
}

