/* Бот присылает JSON-файлы двух типов (различаются полем type):
     teams    — команды и свободные агенты. Полностью заменяет список команд,
                сбрасывает сетку (матчи) и расписание;
     settings — данные турнира. Команды и матчи не трогает.
   Разбор, проверка и нормализация — чистые функции: их вызывает и интерфейс,
   и автотесты (tests/admin-import.mjs). */

var BOT_ROLES = {
    dota2: { label: 'Dota 2', roles: { 1: 'Керри', 2: 'Мидер', 3: 'Офлейн', 4: 'Саппорт 4', 5: 'Саппорт 5' } },
    csgo: { label: 'CS:GO', roles: { 1: 'IGL', 2: 'AWPer', 3: 'Entry', 4: 'Support', 5: 'Lurker' } }
};

var BOT_PENDING = null;   /* разобранный файл, ожидающий подтверждения */
var BOT_STEP = null;      /* текущий шаг подтверждения */

function botDisciplineInfo(code) {
    if (BOT_ROLES[code]) return BOT_ROLES[code];
    return { label: code ? String(code) : 'неизвестная дисциплина', roles: null };
}
function pluralPlayers(n) {
    var m10 = n % 10, m100 = n % 100;
    if (m10 === 1 && m100 !== 11) return 'игрок';
    if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'игрока';
    return 'игроков';
}
function pluralAgents(n) {
    var m10 = n % 10, m100 = n % 100;
    if (m10 === 1 && m100 !== 11) return 'агент';
    if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return 'агента';
    return 'агентов';
}
function botGameKey(value) {
    return String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

/* ---------- 1. Разбор файла ---------- */
function botParseFile(text) {
    var doc;
    try {
        doc = JSON.parse(text);
    } catch (err) {
        return { ok: false, error: '❌ Файл повреждён: не удалось прочитать JSON. Проверь, что выбран файл, который прислал бот.' };
    }
    if (!doc || typeof doc !== 'object' || Array.isArray(doc)) {
        return { ok: false, error: '❌ Это не файл от бота.' };
    }
    if (!doc.type) {
        return { ok: false, error: '❌ Это не файл от бота: внутри нет поля "type".' };
    }
    if (doc.type !== 'teams' && doc.type !== 'settings') {
        return { ok: false, error: '❌ Это не файл от бота: неизвестный type "' + String(doc.type) + '" (ожидается "teams" или "settings").' };
    }
    if (Number(doc.version) !== 1) {
        return { ok: false, error: '❌ Файл из будущей версии. Обнови админку.' };
    }
    return { ok: true, doc: doc };
}

/* ---------- 2. Проверка содержимого ---------- */
function botValidateTeams(doc) {
    var errors = [];
    var info = botDisciplineInfo(doc.discipline);
    if (!info.roles) errors.push('Неизвестная дисциплина: ' + info.label + '.');

    if (!Array.isArray(doc.teams)) {
        return { ok: false, errors: ['Нет списка команд (поле teams).'] };
    }
    if (!doc.teams.length) errors.push('В файле нет ни одной команды.');

    for (var i = 0; i < doc.teams.length; i++) {
        var t = doc.teams[i] || {};
        var name = typeof t.name === 'string' ? t.name.trim() : '';
        var label = 'Команда ' + (i + 1) + (name ? ' «' + name + '»' : '');
        if (!name) errors.push(label + ': не указано название.');
        else if (name.length < 2 || name.length > 30) errors.push(label + ': название должно быть от 2 до 30 символов.');

        if (!Array.isArray(t.players)) {
            errors.push(label + ': нет состава (players).');
            continue;
        }
        if (t.players.length !== 5) {
            errors.push(label + ': ' + t.players.length + ' ' + pluralPlayers(t.players.length) + ' вместо 5.');
            continue;
        }
        for (var k = 0; k < t.players.length; k++) {
            var p = t.players[k] || {};
            var nick = typeof p.nick === 'string' ? p.nick.trim() : '';
            if (nick.length < 2 || nick.length > 30) {
                errors.push(label + ', игрок ' + (k + 1) + ': ник должен быть от 2 до 30 символов' + (nick ? ' («' + nick + '»)' : '') + '.');
            }
            var role = parseInt(p.role, 10);
            if (info.roles && !info.roles[role]) {
                var raw = (p.role === undefined || p.role === null || p.role === '') ? 'не указана' : '"' + p.role + '"';
                errors.push(label + ', игрок ' + (k + 1) + ': роль ' + raw + ' не подходит для ' + info.label + '.');
            }
        }
    }
    return { ok: errors.length === 0, errors: errors };
}

function botValidateSettings(doc) {
    var errors = [];
    if (!doc.tournament || typeof doc.tournament !== 'object' || Array.isArray(doc.tournament)) {
        errors.push('Нет блока tournament с настройками турнира.');
    } else if (!doc.tournament.name) {
        errors.push('В настройках нет названия турнира (tournament.name).');
    }
    if (!doc.discipline) errors.push('Нет поля discipline (для какой игры настройки).');
    return { ok: errors.length === 0, errors: errors };
}

/* ---------- 3. Нормализация ---------- */
function botDuplicates(teams) {
    var seen = {};
    var out = [];
    for (var i = 0; i < teams.length; i++) {
        var t = teams[i] || {};
        var key = String(t.name || '').trim().toLowerCase();
        if (!key) continue;
        if (seen[key] === undefined) {
            seen[key] = { name: String(t.name).trim(), count: 1, positions: [i + 1] };
            out.push(seen[key]);
        } else {
            seen[key].count++;
            seen[key].positions.push(i + 1);
        }
    }
    return out.filter(function (d) { return d.count > 1; });
}

function botNormalizeAgents(list) {
    var out = [];
    if (!Array.isArray(list)) return out;
    for (var i = 0; i < list.length; i++) {
        var p = list[i] || {};
        out.push({
            nick: String(p.nick || '').trim(),
            role: parseInt(p.role, 10) || 0,
            roleLabel: p.roleLabel ? String(p.roleLabel) : '',
            rank: p.rank ? String(p.rank) : '',
            note: p.note ? String(p.note) : '',
            telegramId: p.telegramId || null,
            type: p.type === 'player' ? 'player' : 'looking_for_team'
        });
    }
    return out;
}

/* strategy: 'replace' — при повторе названия оставить последнюю команду,
             'skip'    — оставить первую */
function botNormalizeTeams(doc, strategy) {
    var source = Array.isArray(doc.teams) ? doc.teams : [];
    var index = {};
    var picked = [];
    for (var i = 0; i < source.length; i++) {
        var t = source[i] || {};
        var key = String(t.name || '').trim().toLowerCase();
        if (index[key] !== undefined) {
            if (strategy === 'skip') continue;
            picked[index[key]] = t;
            continue;
        }
        index[key] = picked.length;
        picked.push(t);
    }

    var teams = [];
    for (var j = 0; j < picked.length; j++) {
        var src = picked[j] || {};
        var players = [];
        var srcPlayers = Array.isArray(src.players) ? src.players : [];
        for (var k = 0; k < srcPlayers.length; k++) {
            var p = srcPlayers[k] || {};
            players.push({
                nick: String(p.nick || '').trim(),
                role: parseInt(p.role, 10),
                roleLabel: p.roleLabel ? String(p.roleLabel) : ''
            });
        }
        teams.push({
            id: j + 1,                                   /* id 1..N в порядке файла */
            name: String(src.name || '').trim(),
            logo: typeof src.logo === 'string' ? src.logo : '',
            logoOversized: !!src.logoOversized,
            players: players
        });
    }
    return { teams: teams, agents: botNormalizeAgents(doc.freeAgents) };
}

/* ---------- 4. Интерфейс: приём файла ---------- */
function botShowImportStatus(cls, html) {
    var box = document.getElementById('botImportStatus');
    if (!box) return;
    box.className = 'archive-status ' + cls;
    box.innerHTML = html;
}
function botShowImportError(message) {
    botShowImportStatus('warn', '<div class="as-text">' + message + '</div>' +
        '<div class="as-actions"><button class="btn btn-sm" onclick="botShowCurrentState()">🔄 Что сейчас в админке</button></div>');
    showToast('❌ Импорт не выполнен');
}
function botShowImportErrors(fileName, errors) {
    var shown = errors.slice(0, 8);
    var html = '<div class="as-text"><b>Файл «' + escapeHtml(fileName) + '» не импортирован.</b>' +
        ' Найдено проблем: ' + errors.length + '.</div>' +
        '<div class="bot-mistakes">' + shown.map(function (e) { return escapeHtml(e); }).join('<br>') +
        (errors.length > shown.length ? '<br>…и ещё ' + (errors.length - shown.length) : '') + '</div>';
    botShowImportStatus('warn', html);
    showToast('❌ В файле ошибки — импорт отменён');
}

function onBotFileChosen(event) {
    var input = event && event.target ? event.target : null;
    var file = input && input.files ? input.files[0] : null;
    if (!file) return;
    var fileName = file.name || 'файл';

    var reader = new FileReader();
    reader.onload = function (e) {
        var text = String(e && e.target ? e.target.result : '');
        botHandleText(text, fileName);
    };
    reader.onerror = function () {
        botShowImportError('❌ Не удалось прочитать файл «' + escapeHtml(fileName) + '». Попробуй ещё раз.');
    };
    reader.readAsText(file);
    if (input) input.value = '';
}

/* Главная точка входа: текст файла + его имя */
function botHandleText(text, fileName) {
    var name = fileName || 'файл';
    var parsed = botParseFile(text);
    if (!parsed.ok) { botShowImportError(parsed.error); return false; }

    var doc = parsed.doc;

    if (doc.type === 'teams') {
        var check = botValidateTeams(doc);
        if (!check.ok) { botShowImportErrors(name, check.errors); return false; }

        var duplicates = botDuplicates(doc.teams);
        BOT_PENDING = {
            doc: doc, kind: 'teams', fileName: name,
            duplicates: duplicates, teams: null, agents: null, strategy: null
        };
        if (duplicates.length) botOpenStep('duplicates');
        else botConfirmDuplicates('replace');
        return true;
    }

    var checkS = botValidateSettings(doc);
    if (!checkS.ok) { botShowImportErrors(name, checkS.errors); return false; }

    BOT_PENDING = { doc: doc, kind: 'settings', fileName: name, duplicates: [], teams: null, agents: null, strategy: null };
    botOpenStep('settings');
    return true;
}

function botPlan() {
    if (!BOT_PENDING) return null;
    if (!BOT_PENDING.teams) {
        var plan = botNormalizeTeams(BOT_PENDING.doc, BOT_PENDING.strategy || 'replace');
        BOT_PENDING.teams = plan.teams;
        BOT_PENDING.agents = plan.agents;
    }
    return BOT_PENDING;
}

/* ---------- 5. Шаги подтверждения ---------- */
function botCloseModal() {
    var el = document.getElementById('botModal');
    if (el) el.classList.remove('active');
}
function botImportCancel() {
    botCloseModal();
    BOT_PENDING = null;
    BOT_STEP = null;
    botShowImportStatus('neutral', '<div class="as-text">Импорт отменён — данные не изменились.</div>');
    showToast('Импорт отменён');
}
function botSetActions(list) {
    var box = document.getElementById('botModalActions');
    if (!box) return;
    var html = '';
    for (var i = 0; i < list.length; i++) {
        html += '<button class="btn ' + (list[i].cls || '') + '" onclick="' + list[i].action + '">' + list[i].label + '</button>';
    }
    box.innerHTML = html;
}
function botFileSummary() {
    var plan = botPlan();
    if (!plan) return '';
    var doc = plan.doc;
    var info = botDisciplineInfo(doc.discipline);
    var oversized = 0;
    for (var i = 0; i < plan.teams.length; i++) if (plan.teams[i].logoOversized) oversized++;

    return '<div class="bd-row"><span class="bd-key">Файл</span><span class="bd-val">' + escapeHtml(plan.fileName) + '</span></div>' +
        '<div class="bd-row"><span class="bd-key">Тип</span><span class="bd-val">' + (plan.kind === 'teams' ? 'команды (teams)' : 'настройки (settings)') + '</span></div>' +
        '<div class="bd-row"><span class="bd-key">Дисциплина</span><span class="bd-val">' + escapeHtml(info.label) + '</span></div>' +
        (plan.kind === 'teams'
            ? '<div class="bd-row"><span class="bd-key">Команд в файле</span><span class="bd-val">' + plan.teams.length + '</span></div>' +
              '<div class="bd-row"><span class="bd-key">Свободных агентов</span><span class="bd-val">' + plan.agents.length + '</span></div>' +
              (oversized ? '<div class="bd-row"><span class="bd-key">Логотипы</span><span class="bd-val">⚠️ у ' + oversized + ' команд логотип больше 200 КБ</span></div>' : '')
            : '');
}

function botOpenStep(step) {
    BOT_STEP = step;
    var title = document.getElementById('botModalTitle');
    var body = document.getElementById('botModalBody');
    if (!title || !body) return;

    if (step === 'duplicates') {
        var plan = botPlan();
        var rows = '';
        for (var i = 0; i < plan.duplicates.length; i++) {
            var d = plan.duplicates[i];
            rows += '<div class="bot-item"><div class="bi-info"><span class="bi-name">' + escapeHtml(d.name) + '</span>' +
                '<span class="bi-meta">повторяется ' + d.count + ' раза · команды №' + d.positions.join(', ') + '</span></div></div>';
        }
        title.textContent = '🔁 Повторяющиеся названия';
        body.innerHTML = '<div class="bd-warn">⚠️ В файле есть команды с одинаковыми названиями.</div>' +
            '<div>Оставить последнюю версию (заменить) или первую (пропустить повторы)?</div>' +
            '<div class="bot-list">' + rows + '</div>';
        botSetActions([
            { label: '🔁 Заменить', action: "botConfirmDuplicates('replace')", cls: 'btn-primary' },
            { label: '⏭ Пропустить', action: "botConfirmDuplicates('skip')" },
            { label: '◀ Отмена', action: 'botImportCancel()' }
        ]);
    } else if (step === 'teams-replace') {
        title.textContent = '📥 Импорт команд';
        body.innerHTML = '<div class="bd-warn">⚠️ Импорт заменит список команд полностью.</div>' +
            '<div>Сейчас в админке команд: ' + (Array.isArray(DATA.teams) ? DATA.teams.length : 0) + '.</div>' +
            '<div class="bot-details">' + botFileSummary() + '</div>';
        botSetActions([
            { label: '✅ Продолжить', action: 'botStepToMatches()', cls: 'btn-primary' },
            { label: '◀ Отмена', action: 'botImportCancel()' }
        ]);
    } else if (step === 'matches-reset') {
        var played = 0;
        for (var k = 0; k < DATA.matches.length; k++) if (DATA.matches[k] && DATA.matches[k].winner) played++;
        title.textContent = '⚠️ Сброс сетки';
        body.innerHTML = '<div class="bd-warn">⚠️ Импорт команд сбросит текущую сетку (матчи и расписание).' +
            ' Все пары нужно будет расставить заново.</div>' +
            '<div>Сейчас в сетке матчей с результатом: ' + played + '.</div>' +
            '<div class="bot-details">' + botFileSummary() + '</div>';
        botSetActions([
            { label: '✅ Продолжить', action: 'botApplyTeams()', cls: 'btn-primary' },
            { label: '◀ Отмена', action: 'botImportCancel()' }
        ]);
    } else if (step === 'settings') {
        var t = (BOT_PENDING && BOT_PENDING.doc ? BOT_PENDING.doc.tournament : {}) || {};
        var rows2 = '';
        var pairs = [
            ['Название', DATA.tournament.name, t.name],
            ['Игра', DATA.tournament.game, t.game],
            ['Формат', DATA.tournament.format, t.format],
            ['Матчи', DATA.tournament.matches, t.matches],
            ['Даты', DATA.tournament.dates, t.dates]
        ];
        for (var m = 0; m < pairs.length; m++) {
            rows2 += '<div class="bd-row"><span class="bd-key">' + pairs[m][0] + '</span><span class="bd-val">' +
                escapeHtml(pairs[m][1] || '—') + ' → <b>' + escapeHtml(pairs[m][2] || '—') + '</b></span></div>';
        }
        title.textContent = '⚙️ Настройки турнира';
        body.innerHTML = 'Из файла <b>' + escapeHtml(BOT_PENDING.fileName) + '</b> будут применены настройки турнира.' +
            '<div>Команды и сетка матчей не изменятся.</div>' +
            '<div class="bot-details" style="margin-top:10px;">' + rows2 + '</div>';
        botSetActions([
            { label: '✅ Применить', action: 'botApplySettings()', cls: 'btn-primary' },
            { label: '◀ Отмена', action: 'botImportCancel()' }
