    }

    document.getElementById('botModal').classList.add('active');
}

function botConfirmDuplicates(strategy) {
    if (!BOT_PENDING) return;
    BOT_PENDING.strategy = strategy;
    botPlan();
    botOpenStep('teams-replace');
}
function botStepToMatches() {
    if (!BOT_PENDING) return;
    botOpenStep('matches-reset');
}

/* ---------- 6. Применение ---------- */
function botApplyTeams() {
    var plan = botPlan();
