function botTeamsDoc(teams, freeAgents, discipline) { return { type: 'teams', version: 1, exportedAt: ..., discipline: discipline || 'dota2', teams, freeAgents: freeAgents || [] }; }
function botTeam(name, opts) { return { id: ..., num: ..., name, logo: opts.logo || '', logoOversized: !!opts.oversized, captainNick: '@cap', captainTelegramId: 1, players: players } }
const FIVE = [['Yatoro',1],['Larl',2],['Collapse',3],['Mira',4],['Miposhka',5]];

