  tournament: {...}, teams: [...6 placeholder teams], matches: [...with winners...], schedule: {1:'...'}, liveMatchId: null, nextSeason: null, alwaysShowBanner..., history: []
};

async function boot(initial) { ... same as admin-archive but returning w/state ... }

function fakeReader(win, text) {
  win.FileReader = function () { this.readAsText = function () { var self = this; setTimeout(function () { if (self.onload) self.onload({ target: { result: text } }); }, 0); }; };
}
function chooseFile(w, text, name) {
  fakeReader(w, text);
  w.onBotFileChosen({ target: { files: [{ name: name || 'teams.json' }], value: 'x' } });
}
