const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const DP = [ {nick:'Yatoro',role:1,roleLabel:'Керри'},{nick:'Larl',role:2,roleLabel:'Мидер'},{nick:'Collapse',role:3,roleLabel:'Офлейн'},{nick:'Mira',role:4,roleLabel:'Саппорт 4'},{nick:'Miposhka',role:5,roleLabel:'Саппорт 5'} ];
const bt = (name, players) => ({ id:'team_1', num:1, name, logo:'', players: players || DP });
const mk = () => ({ tournament:{name:'CA',game:'Dota 2',format:'CB',matches:'Bo3',dates:'x'}, teams:[{id:1,name:'Старая',logo:'',players:[]}], matches:[1,2,3,4,5].map(i=>({id:i,round:1,team1:null,team2:null,winner:null,bracket:'upper',score1:null,score2:null,vod:''})), schedule:{}, liveMatchId:null, freeAgents:[], history:[] });
async function boot() {
  const state = { data: mk(), saves: [] };
  const vc = new VirtualConsole(); vc.on('jsdomError', e => console.log('JSDOM ERR:', e.message));
  const dom = new JSDOM(read('poasalj1.z23.html'), { url:'https://x/admin', runScripts:'dangerously', virtualConsole: vc, beforeParse(win){
    win.confirm = () => true; win.prompt = () => 'pw';
    win.fetch = async (u,o) => { if (String(u).includes('/api/save')) { state.saves.push(JSON.parse(o.body).data); return { ok:true,status:200,json:async()=>({ok:true}) }; } return { ok:true,status:200,json:async()=>JSON.parse(JSON.stringify(state.data)) }; };
  }});
  await sleep(150);
  return { w: dom.window, state };
}
const doc = { type:'teams', version:1, discipline:'dota2', teams:[ bt('Team Spirit', [{nick:'Первая',role:1,roleLabel:'x'}].concat(DP.slice(1))), bt('Другая'), bt('Team Spirit', [{nick:'Вторая',role:1,roleLabel:'x'}].concat(DP.slice(1))) ], freeAgents:[] };
const content = JSON.stringify(doc);
async function run(label) {
  const { w, state } = await boot();
  w.FileReader = function () { const s = this; this.readAsText = function () { setTimeout(() => s.onload({ target: { result: content } }), 0); }; };
  w.onBotFileChosen({ target: { files: [{ name: 'f.json' }], value: 'x' } });
  await sleep(40);
  console.log(label, '| шаг 1:', w.document.getElementById('botModalTitle').textContent, '| кнопки:', Array.from(w.document.querySelectorAll('#botModalActions button')).map(b=>b.textContent.trim()).join('/'));
  const skip = Array.from(w.document.querySelectorAll('#botModalActions button')).find(b => b.textContent.indexOf('Пропустить') >= 0);
  if (skip) skip.click(); else console.log(label, 'КНОПКИ ПРОПУСТИТЬ НЕТ');
  await sleep(20);
  console.log(label, '| шаг 2:', w.document.getElementById('botModalTitle').textContent, '| strategy:', w.BOT_PENDING && w.BOT_PENDING.strategy);
  return { w, state };
}
const a = await run('первый запуск');
const b = await run('второй запуск');
