export const SITE_URL = 'https://compass-arena-test.pages.dev';
export const CONTACTS = '@G0gg1a · @uuutt7';
export const DEFAULT_TOURNAMENT = 'Compass Arena Season 2';

/** Строка с сайтом — для финальных сообщений */
export const siteLine = () => `Сайт: ${SITE_URL}`;
/** Строка со связью */
export const contactLine = () => `Связь: ${CONTACTS}`;
/** Блок «сайт + связь» */
export const contactsBlock = () => `${siteLine()}\n${contactLine()}`;
/** Напоминание об отмене на шагах с вводом */
export const CANCEL_HINT = '\n\nОтмена: /cancel';
/** Заголовок шага: «Шаг 2 из 7» */
export const stepTitle = (step, total) => `<b>Шаг ${step} из ${total}</b>`;
export const ERROR_PREFIX = '⚠️ ';
