      'В Telegram нет @username, поэтому нужен ник вручную.' + CANCEL_HINT
    ].filter(Boolean).join('\n'),
    keyboard: kb([
      [{ text: 'Взять ник игрока 1', data: 'reg:skip:captain' }],
      backRow()
    ])
  };
}

function screenTeamPlayerNick(temp, note) {
