    if (p.teamName) lines.push(`Команда: ${esc(p.teamName)}`);
    lines.push(`Позиция: ${esc(p.roleLabel || p.role || '—')}`);
  }

  lines.push('');
  const username = author && author.username ? '@' + esc(author.username) + ' ' : '';
