  ok(/Проверка заявки/.test(lastTo(USER)), 'карточка подписана «Проверка заявки»');
  ok(/Miposhka — Саппорт 5/.test(lastTo(USER)), 'в карточке пятый игрок с ролью');
  ok(/1\. Yatoro — Керри/.test(lastTo(USER)), 'в карточке первый игрок с ролью');
  ok(/Логотип: загружен/.test(lastTo(USER)), 'в карточке видно, что логотип загружен');
  ok(/Капитан: @tester/.test(lastTo(USER)), 'в карточке указан капитан');

  await tap(env, USER, 'reg:confirm');
  ok(/отправлена на модерацию/.test(lastTo(USER)), 'заявка отправлена на модерацию');
