{"content": "/* Одноразовый ремонт файла, пострадавшего от PowerShell 5.1:
   UTF-8 → прочитан как CP1251 → записан как UTF-8 (двойная кодировка).
   Обратный проход: символ → байт CP1251 → декодируем как UTF-8. */
import fs from 'node:fs';

const path = process.argv[2];
const raw = fs.readFileSync(path);
const broken = raw.toString('utf8');

const decoder = new TextDecoder('windows-1251');
const charToByte = new Map();
for (let b = 0; b < 256; b++) {
  const ch = decoder.decode(new Uint8Array([b]));
  if (ch.length === 1 && !charToByte.has(ch)) charToByte.set(ch, b);
}

const bytes = [];
let unknown = 0;
for (const ch of broken) {
  const code = ch.codePointAt(0);
  if (code < 128) {
    bytes.push(code);
    continue;
  }
  if (charToByte.has(ch)) {
    bytes.push(charToByte.get(ch));
    continue;
  }
  unknown++;
  bytes.push(0x3F); // «?» — если такой символ найдётся, будет видно
}

const fixed = Buffer.from(bytes).toString('utf8');
fs.writeFileSync(path, fixed, 'utf8');
console.log('неизвестных символов:', unknown);
console.log('строк:', fixed.split('\n').length);
console.log('проверка:', fixed.includes('Пройдено') ? 'кириллица восстановлена' : 'КИРИЛЛИЦА НЕ ВОССТАНОВЛЕНА');
", "file_path": "bot\scripts\fix-encoding.mjs"}

