{"content": "/* Временный скрипт: печатает все пользовательские тексты бота для сверки со ТЗ */
import { handleUpdate } from '../src/index.js';
import { createFakeD1 } from './fake-d1.mjs';

const calls = [];
globalThis.fetch = async (url, init = {}) => {
  const s = String(url);
  if (s.includes('/file/bot')) return { ok: true, status: 200, arrayBuffer: async () => new Uint8Array(4).buffer };
  const method = s.split('/').pop().split('?')[0];
  let body = null;
  if (typeof init.body === 'string') { try { body = JSON.parse(init.body); } catch { body = init.body; } }
  calls.push({ method, body });
  if (method === 'getFile') return { ok: true, status: 200, json: async () => ({ ok: true, result: { file_id: 'x', file_size: 80 * 1024, file_path: 'x.jpg' } }) };
  return { ok: true, status: 200, json: async () => ({ ok: true, result: { message_id: calls.length } }) };
};

const fake = createFakeD1();
const env = {
  BOT_TOKEN: 't', ADMIN_ID: '111', WEBHOOK_SECRET: 's', ENVIRONMENT: 'development',
  LEAD_RATE_LIMIT_SEC: '300', LOGO_MAX_KB: '200', DB: fake.DB, _db: fake._db
};
const U = 900;
const A = 111;
const from = (id) => ({ id, username: 'tester', first_name: 'T' });
const msg = (id, text) => ({ update_id: 1, message: { message_id: 9, from: from(id), chat: { id }, text } });
const cb = (id, data) => ({ update_id: 2, callback_query: { id: 'c', from: from(id), data, message: { message_id: 9, chat: { id } } } });
const photo = (id) => ({ update_id: 3, message: { message_id: 9, from: from(id), chat: { id }, photo: [{ file_id: 'p', width: 800 }] } });

const mark = () => calls.length;
function dump(title, from_) {
  const items = calls.slice(from_).filter((c) => c.method === 'sendMessage' || c.method === 'editMessageText');
  console.log('\n=== ' + title + ' ===');
  for (const item of items) {
    const kb = item.body.reply_markup
      ? '\n   [кнопки: ' + item.body.reply_markup.inline_keyboard.map((row) => row.map((b) => b.text).join(' | ')).join(' ][ ') + ']'
      : '';
    console.log('--- ' + item.body.text + kb);
  }
}

let m = mark();
await handleUpdate(env, msg(U, '/start'));
dump('/start (меню)', m);

m = mark();
await handleUpdate(env, msg(U, '/help'));
dump('/help (игрок)', m);

m = mark();
await handleUpdate(env, msg(A, '/help'));
dump('/help (админ)', m);

m = mark();
await handleUpdate(env, msg(U, '/чепуха'));
dump('неизвестная команда', m);

// Ветка A
m = mark();
await handleUpdate(env, cb(U, 'reg:disc:dota2'));
await handleUpdate(env, cb(U, 'reg:type:team'));
await handleUpdate(env, msg(U, 'Team Spirit'));
await handleUpdate(env, photo(U));
await handleUpdate(env, msg(U, 'Yatoro'));
await handleUpdate(env, cb(U, 'reg:role:1'));
await handleUpdate(env, msg(U, 'Larl'));
await handleUpdate(env, cb(U, 'reg:role:2'));
await handleUpdate(env, msg(U, 'Collapse'));
await handleUpdate(env, cb(U, 'reg:role:3'));
await handleUpdate(env, msg(U, 'Mira'));
await handleUpdate(env, cb(U, 'reg:role:4'));
await handleUpdate(env, msg(U, 'Miposhka'));
await handleUpdate(env, cb(U, 'reg:role:5'));
await handleUpdate(env, cb(U, 'reg:confirm'));
dump('ветка A: шаги и финал', m);

// Ошибки ветки A
m = mark();
await handleUpdate(env, msg(U, 'X'));
await handleUpdate(env, cb(U, 'reg:disc:csgo'));
await handleUpdate(env, cb(U, 'reg:type:team'));
await handleUpdate(env, msg(U, 'OG'));
await handleUpdate(env, msg(U, 'не фото'));
await handleUpdate(env, msg(U, '/skip'));
dump('ветка A: ошибки и /skip на логотипе', m);

// Ветка B
m = mark();
await handleUpdate(env, cb(U, 'reg:disc:csgo'));
await handleUpdate(env, cb(U, 'reg:type:looking'));
await handleUpdate(env, msg(U, 's1mple'));
await handleUpdate(env, cb(U, 'reg:role:AWP'));
await handleUpdate(env, msg(U, 'Premier 21 000'));
await handleUpdate(env, msg(U, 'Играю вечером'));
dump('ветка B: шаги и финал', m);

// Ветка C
m = mark();
await handleUpdate(env, cb(U, 'reg:disc:dota2'));
await handleUpdate(env, cb(U, 'reg:type:player'));
await handleUpdate(env, msg(U, 'Nightfall'));
await handleUpdate(env, msg(U, 'Virtus.pro'));
await handleUpdate(env, cb(U, 'reg:role:1'));
dump('ветка C: шаги и финал', m);

// Модерация
m = mark();
await handleUpdate(env, msg(A, '/leads'));
await handleUpdate(env, cb(A, 'mod:list:new'));
await handleUpdate(env, cb(A, 'mod:approve:1'));
await handleUpdate(env, cb(A, 'mod:reject:2'));
await handleUpdate(env, msg(A, 'Не подходит ранг'));
dump('модерация', m);

// Экспорт
m = mark();
await handleUpdate(env, msg(A, '/export'));
await handleUpdate(env, cb(A, 'exp:disc:both'));
await handleUpdate(env, cb(A, 'exp:target:both:teams'));
dump('экспорт', m);
", "file_path": "bot\scripts\.tmp-texts.mjs"}

