export function inlineKeyboard(rows) {
  const keyboard = [];
  for (const row of (rows || [])) {
    const buttons = normalizeButtons(row);
    if (!buttons.length) {
      console.warn('[keyboard] пустая строка клавиатуры пропущена');
      continue;
