  }]));
  rows.push([{ text: 'ℹ️ Справка', data: 'act:help' }]);

  const text = [intro, welcomeText()].filter(Boolean).join('\n\n');
  await sendMessage(env, chatId, text, { keyboard: inlineKeyboard(rows) });
}
