{"content": "/* Сравнение рабочей папки с копиями: что копировать для деплоя.
   Запуск: node compare-copies.mjs "путь-к-копии" ... */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const WS = process.cwd();
const SKIP = /(^|\\)(node_modules|\.npm-cache|\.wrangler|\.git|dist)(\\|$)/;

function walk(dir, base = dir, out = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (SKIP.test(full)) continue;
    if (entry.name === '.dev.vars') continue; // локальные секреты не сравниваем
    if (entry.isDirectory()) walk(full, base, out);
    else out.push(path.relative(base, full));
  }
  return out;
}

const hash = (file) => {
  try {
    return crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex').slice(0, 12);
  } catch {
    return null;
  }
};

const wsFiles = walk(WS).sort();

for (const target of process.argv.slice(2)) {
  console.log('\n=== ' + target + ' ===');
  if (!fs.existsSync(target)) {
    console.log('  папки нет');
    continue;
  }
  const missing = [];
  const different = [];
  let same = 0;
  for (const rel of wsFiles) {
    const mine = hash(path.join(WS, rel));
    const theirs = hash(path.join(target, rel));
    if (theirs === null) missing.push(rel);
    else if (theirs !== mine) different.push(rel);
    else same++;
  }
  console.log('  совпадает: ' + same + ' | отличается: ' + different.length + ' | нет файла: ' + missing.length);
  if (different.length) console.log('  ИЗМЕНЕНЫ:\n    ' + different.join('\n    '));
  if (missing.length) console.log('  НЕТ В КОПИИ:\n    ' + missing.join('\n    '));

  // что есть в копии, но нет у меня (удалённые файлы)
  const theirFiles = new Set(walk(target));
  const extra = Array.from(theirFiles).filter((f) => !wsFiles.includes(f));
  if (extra.length) console.log('  ТОЛЬКО В КОПИИ:\n    ' + extra.join('\n    '));
}
", "file_path": "compare-copies.mjs"}

