{"content": "/* Сравнение двух деревьев проекта: что изменилось.
   Запуск: node tree-diff.mjs <левое(проверяемое)> <правое(эталон)> [--diff] */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const [left, right, ...flags] = process.argv.slice(2);
const SHOW_DIFF = flags.includes('--diff');
const SKIP = /(^|[\\/])(node_modules|\.npm-cache|\.wrangler|\.git|dist)([\\/]|$)/;
const IGNORE_FILES = new Set(['.dev.vars']);

function walk(dir, base = dir, out = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    const rel = path.relative(base, full);
    if (SKIP.test(full) || IGNORE_FILES.has(entry.name)) continue;
    if (entry.isDirectory()) walk(full, base, out);
    else out.push(rel);
  }
  return out;
}

const readFile = (p) => { try { return fs.readFileSync(p); } catch { return null; } };
const hash = (buf) => (buf ? crypto.createHash('sha256').update(buf).digest('hex').slice(0, 12) : null);
const text = (buf) => (buf && buf.length < 400000 && !buf.includes(0) ? buf.toString('utf8') : null);

const leftFiles = new Set(walk(left));
const rightFiles = new Set(walk(right));

const onlyLeft = [...leftFiles].filter((f) => !rightFiles.has(f)).sort();
const onlyRight = [...rightFiles].filter((f) => !leftFiles.has(f)).sort();
const changed = [];
for (const rel of [...leftFiles].filter((f) => rightFiles.has(f)).sort()) {
  const a = readFile(path.join(left, rel));
  const b = readFile(path.join(right, rel));
  if (hash(a) !== hash(b)) changed.push({ rel, a, b });
}

console.log('ПРОВЕРЯЕМ : ' + left);
console.log('ЭТАЛОН   : ' + right);
console.log('файлов: ' + leftFiles.size + ' против ' + rightFiles.size);
console.log('\n--- изменено: ' + changed.length + ' ---');
for (const c of changed) {
  const la = text(c.a), lb = text(c.b);
  let note = '';
  if (la && lb) {
    const al = la.split('\n'), bl = lb.split('\n');
    note = ' (строк ' + bl.length + ' → ' + al.length + ')';
  } else {
    note = ' (двоичный или большой: ' + (c.b ? c.b.length : 0) + ' → ' + (c.a ? c.a.length : 0) + ' байт)';
  }
  console.log('  ' + c.rel + note);
}
console.log('\n--- только в ' + path.basename(left) + ': ' + onlyLeft.length + ' ---');
onlyLeft.forEach((f) => console.log('  ' + f));
console.log('\n--- только в эталоне: ' + onlyRight.length + ' ---');
onlyRight.forEach((f) => console.log('  ' + f));

if (SHOW_DIFF) {
  for (const c of changed) {
    const la = text(c.a), lb = text(c.b);
    if (!la || !lb) continue;
    const al = la.split('\n'), bl = lb.split('\n');
    console.log('\n===== ' + c.rel + ' =====');
    const max = Math.max(al.length, bl.length);
    let shown = 0;
    for (let i = 0; i < max && shown < 40; i++) {
      if (al[i] !== bl[i]) {
        shown++;
        if (bl[i] !== undefined) console.log('  эталон ' + (i + 1) + ': ' + bl[i].trim().slice(0, 150));
        if (al[i] !== undefined) console.log('  сейчас ' + (i + 1) + ': ' + al[i].trim().slice(0, 150));
      }
    }
    if (shown === 0) console.log('  (различия только в конце файла/переводах строк)');
  }
}
