const fs=require('fs'),path=require('path');
const src=process.argv[1];
const start=fs.readFileSync(path.join(src,'handlers/start.js'),'utf8');
const imports=[...start.matchAll(/import \{([^}]+)\} from '([^']+)'/g)];
for(const m of imports){
  const names=m[1].split(',').map(s=>s.trim()).filter(Boolean);
  const file=path.join(src,m[2].replace('../',''));
  const code=fs.existsSync(file)?fs.readFileSync(file,'utf8'):null;
  if(!code){console.log('  '+m[2]+' — НЕТ ФАЙЛА');continue;}
  const missing=names.filter(n=>!new RegExp('export (async )?(function|const|class) '+n+'\\\\b').test(code) && !new RegExp('export \\\\{[^}]*\\\\b'+n+'\\\\b').test(code));
  console.log('  '+m[2]+': '+(missing.length?('ОТСУТСТВУЮТ ЭКСПОРТЫ: '+missing.join(', ')):'все экспорты на месте'));
}
